INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-ez-bar-biceps-curl', 'EZ杆二头弯举', 'ez bar biceps curl', 'arms', 'barbell', 1, 1, '双脚与肩同宽站立，以反握握住EZ杆内侧的斜握位。
让杆以手臂长度垂在大腿前方。
保持肘部不动，将杆向上弯举至肩部。
在动作顶端停顿并挤压肱二头肌。
缓慢将杆放回起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-ez-bar-curl', 'EZ杠弯举', 'ez bar curl', 'arms', 'barbell', 1, 1, '直立，双手以肩宽半旋前握距握住曲杆。
让曲杆在髋部前方自然下垂，手臂伸直。
保持肘部贴近躯干，将曲杆弯举向肩部。
在顶端停顿，收缩肱二头肌。
缓慢将曲杆下放回完全伸直的位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-preacher-curl-ez-bar', 'EZ杠牧师凳弯举', 'preacher curl ez bar', 'arms', 'barbell', 0, 2, '坐在牧师凳上，上臂后侧平贴斜垫。
用内侧斜握手柄以反握握住曲杆。
从手臂接近完全伸直开始，收缩肱二头肌将杆向上弯举。
在动作顶端稍作停顿并挤压肱二头肌。
缓慢将杆放回接近伸直的起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-pushdown-cable-rope', '三头肌下压（绳索）', 'triceps pushdown (cable - rope)', 'arms', 'cable', 0, 1, '将绳索手柄连接到绳索器械的高滑轮上，面向器械站立。
双手采用中立握法握住绳索，肘部贴近身体两侧。
伸直手臂将绳索向下推，直到手臂完全伸直。
在底部将绳索两端稍微分开，以最大化三头肌收缩。
缓慢让绳索回到起始位置，重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-bench-dip', '三头肌凳上臂屈伸', 'triceps bench dip', 'arms', 'bodyweight', 1, 1, '坐在长凳边缘，双手置于髋部两侧，手指朝前。
将臀部滑离长凳，双腿向前伸直。
弯曲肘部至约90度，降低身体。
在底部稍作停顿，然后伸直肘部撑起身体。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-cable-pushdown-straight-bar-attachment', '三头肌绳索下压（直杆）', 'triceps cable pushdown (straight bar attachment)', 'arms', 'cable', 1, 1, '将直杆连接至绳索器械的高位滑轮。
面朝器械站立，正握直杆，肘部收紧于身体两侧。
向下推杆直至手臂完全伸直。
在底部稍作停顿，收紧肱三头肌。
缓慢让杆回升至起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-cable-pushdown-rope-attachment', '三头肌绳索下压（绳把）', 'triceps cable pushdown (rope attachment)', 'arms', 'cable', 1, 1, '将绳索连接至绳索器械的高位滑轮，面朝器械站立。
双手握住绳索，肘部置于身体两侧呈90度。
伸直肘部将绳索向下推，在底部将绳端向两侧分开。
手臂完全伸直、肱三头肌收紧时稍作停顿。
缓慢返回起始位置，允许肘部弯曲。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-dips', '三头肌臂屈伸', 'triceps dips', 'arms', 'bodyweight', 1, 1, '坐在稳固椅子或垫子边缘，双手抓住髋部两侧边缘，手指朝前。
将臀部滑离边缘，双腿向前伸直。
弯曲肘部，身体缓慢向地面下降，背部贴近椅子。
肘部约呈90度时停止。
手掌发力，伸直手臂返回起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-incline-dumbbell-curl', '上斜哑铃弯举', 'incline dumbbell curl', 'arms', 'dumbbell', 1, 2, '坐在调至约60度的斜凳上，双手各持哑铃。
双臂自然下垂于身体平面后方，充分拉伸肱二头肌。
上臂保持不动，收缩肱二头肌弯举哑铃。
在顶端稍停，然后缓慢下放回起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-incline-close-grip-half-push-up', '上斜窄距半俯卧撑', 'Incline Close Grip Half Push Up', 'arms', 'bodyweight', 1, 1, '双手略窄于肩，撑在长凳等抬高平面上。
双脚后撤形成一条直线，呈斜面上斜俯卧撑姿势。
胸部下放至一半，肘部弯曲至45度停止。
推回起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-decline-close-push-ups', '下斜窄距俯卧撑', 'Decline Close Push Ups', 'arms', 'bodyweight', 1, 2, '双脚放在长凳或椅子等高处，双手在胸下靠拢成俯卧撑姿势。
身体从头到脚跟保持一条直线。
肘部贴近身体两侧弯曲，胸部向地面下降。
推回起始位置，双臂完全伸展。
重复完成目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-spider-curl', '交替蜘蛛弯举', 'alternating spider curl', 'arms', 'dumbbell', 0, 2, '将上斜凳调至45-60度，面朝下趴于凳上，胸部贴紧靠垫，双臂垂直下垂。
双手各持一只哑铃，采用反握。
保持肘部固定，将两只哑铃向上弯举至肩部。
在动作顶端挤压肱二头肌。
缓慢将哑铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-zottman-curl', '佐特曼弯举', 'zottman curl', 'arms', 'dumbbell', 1, 2, '站立，双手持哑铃于体侧，掌心朝前。
像标准弯举一样，将哑铃向上弯举至肩部。
在动作顶端，旋转手腕使掌心朝下。
保持掌心朝下的姿势，缓慢下放哑铃。
在底部，将手腕旋转回掌心朝上的起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lateral-shuffle-battle-rope', '侧向滑步战绳', 'lateral shuffle battle rope', 'arms', 'other', 1, 2, '以运动姿势站立，双手各握战绳一端。
开始交替甩绳，同时向一侧横向滑步。
滑几步后，继续甩绳并向反方向滑回。
全程保持低重心运动姿势。
持续目标时间。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-push-up-arm-lift', '俯卧撑单臂抬起', 'push up arm lift', 'arms', 'bodyweight', 1, 2, '从标准俯卧撑姿势开始，双手位于肩下，身体成一条直线。
保持核心收紧、身体稳定，将重心移到左手。
抬起右臂离地，屈肘将手拉回体侧。
将右手放回起始位置的地面。
将重心移到右手，重复动作抬起左臂。
按目标次数持续交替两侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-weighted-push-up', '俯卧撑（负重）', 'weighted push up', 'arms', 'bodyweight', 1, 2, '将杠片放在上背部，呈标准俯卧撑姿势，双手略宽于肩。
身体从头到脚跟保持一条直线，收紧核心。
弯曲肘部将胸部降向地面，肘部与身体约呈45度。
通过掌心发力伸直手臂，回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bench-dips-upper-arms', '凳上臂屈伸（上臂）', 'bench dips upper arms', 'arms', 'bodyweight', 1, 1, '坐在长凳或稳固椅子边缘，双手抓住髋部两侧边缘。
将髋部滑离长凳，双腿向前伸出。
缓慢屈肘下降身体，直到肘部达到90度角。
手掌发力伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-high-cable-curl', '单臂高位绳索弯举', 'single arm high cable curl', 'arms', 'cable', 1, 2, '将单手把手设置在高位滑轮上。
面向器械站立，一只手握住把手，手臂在肩部高度完全伸展。
保持上臂不动，将前臂向肱二头肌方向弯举。
在完全收缩位置停顿，挤压肱二头肌。
缓慢将手臂伸回起始位置。
完成目标次数后换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dips', '双杠臂屈伸', 'dips', 'arms', 'bodyweight', 1, 2, '握住双杠，手臂完全伸直支撑体重。
收紧核心，弯曲肘部降低身体，直到上臂与地面平行。
肘部贴近身体，将发力集中在肱三头肌。
在动作底部稍作停顿。
推回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reverse-push-ups', '反向俯卧撑', 'Reverse Push-Ups', 'arms', 'bodyweight', 1, 2, '坐在地面上，屈膝、双脚踩地，双手平放在髋部后方的地面上，手指朝前。
手掌发力将髋部抬离地面。
屈肘，以受控的下沉动作将髋部向地面降低。
发力回到起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reverse-prayer', '反祈祷式', 'Reverse Prayer', 'arms', 'bodyweight', 1, 2, '站直或坐直，双手放到背后，手背相贴。
手指向上旋转，尝试在背后将手掌合拢。
当前臂、手腕和胸部感到拉伸时保持。
保持20-30秒。
放松并根据需要重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-triceps-kickback', '哑铃三头肌后踢', 'dumbbell triceps kickback', 'arms', 'dumbbell', 1, 1, '右手持哑铃，以髋部为轴向前俯身，直到躯干几乎与地面平行。
右肘贴紧身体侧面，上臂与地面平行。
向后上方伸直前臂，直到手臂完全伸直。
在顶端停顿，收紧肱三头肌。
缓慢将哑铃放回起始位置。
完成目标次数后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-biceps-curl-up', '哑铃二头弯举向上', 'dumbbell biceps curl up', 'arms', 'dumbbell', 1, 1, '双手持哑铃站立，掌心朝前，手臂完全伸直。
同时将两个哑铃向上弯举至肩部。
整个动作过程中保持肘部固定并贴近身体两侧。
在顶部停顿并挤压肱二头肌。
控制哑铃缓慢回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cross-body-hammer-curl', '哑铃交叉锤式弯举_版本2', 'cross-body hammer curl', 'arms', 'dumbbell', 1, 1, '双手各持哑铃站立，手臂伸直，掌心朝向躯干。
将右哑铃斜向弯举横过身体，朝左肩方向。
在顶端停顿并挤压肱二头肌。
缓慢将哑铃放回起始位置。
换左臂朝右肩方向弯举重复。
继续交替进行至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-alternating-dumbbell-curl', '哑铃交替弯举', 'alternating dumbbell curl', 'arms', 'dumbbell', 1, 1, '双脚与肩同宽站立，双手各持哑铃，手臂自然下垂伸直。
保持肘部固定，将右哑铃向上弯举至肩部。
在顶端停顿并挤压肱二头肌，然后缓慢放下。
左臂重复该动作。
继续交替两侧至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-skull-crusher', '哑铃仰卧臂屈伸', 'dumbbell skull crusher', 'arms', 'dumbbell', 1, 2, '平躺在长凳上，双手各持一只哑铃，手臂伸直于胸部正上方。
保持上臂垂直于地面，弯曲肘部将哑铃下放至头部两侧。
在头部上方稍作停顿，然后伸直手臂回到起始位置。
整个动作过程中保持肘部朝向天花板。
重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-waiter-curl', '哑铃侍者弯举', 'dumbbell waiter curl', 'arms', 'dumbbell', 1, 1, '站立，双手托住一只哑铃的上方配重片，掌心朝上。
肘部紧贴身体两侧。
屈肘将哑铃向上弯举至下巴方向。
在顶端停顿，收紧肱二头肌。
缓慢将哑铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-farmer-carry', '哑铃农夫行走', 'dumbbell farmer carry', 'arms', 'dumbbell', 1, 2, '双手各持一只重哑铃垂于体侧，手臂完全伸直站立。
收紧核心，肩胛骨后收，挺胸站直。
以可控速度沿直线向前行走，保持身体直立。
整个行走过程中握紧哑铃，步伐稳健。
行走至目标距离或时间后，小心放下哑铃。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-forearms-curl', '哑铃前臂弯举', 'dumbbell forearms curl', 'arms', 'dumbbell', 0, 1, '坐在长凳边缘，前臂放在大腿上，掌心朝上。
双手各持一只哑铃，手腕超出膝盖。
屈腕将哑铃向上弯举。
在动作顶端停顿，收缩前臂肌肉。
缓慢将哑铃放回起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-biceps-isolation-curl', '哑铃孤立弯举', 'biceps isolation curl', 'arms', 'dumbbell', 0, 1, '坐在牧师凳上，或将上臂靠在大腿内侧以孤立肱二头肌。
单手以旋后握法持哑铃，手臂完全伸直。
将哑铃向上弯举至肩部，保持上臂不动。
在动作顶端挤压肱二头肌。
缓慢将哑铃放回起始位置，重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-biceps-curl', '哑铃弯举', 'biceps curl', 'arms', 'dumbbell', 1, 1, '双脚与肩同宽站立，双手各持一只哑铃，手臂伸直，掌心朝前。
保持肘部贴近躯干，将两只哑铃向上弯举至肩部。
在顶端停顿，挤压肱二头肌。
缓慢将哑铃放回起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-kneeling-hammer-curl-to-hammer-press', '哑铃跪姿锤式弯举接锤式推举', 'dumbbell kneeling hammer curl to hammer press', 'arms', 'dumbbell', 1, 1, '双膝跪在垫子上，双手各持一只哑铃，采用中立握法。
以锤式弯举动作将哑铃向上弯举至肩部。
从弯举顶端将哑铃向上推举，直到手臂完全伸直。
将哑铃放回肩部高度，然后继续下放至起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-overhead-triceps-extension-dumbbell', '哑铃过头臂屈伸', 'overhead triceps extension (dumbbell)', 'arms', 'dumbbell', 0, 1, '直立站立或坐姿，双手握住一只哑铃，握住上端配重片。
将哑铃举过头顶，直至双臂完全伸直。
保持上臂靠近头部、肘部朝前，将哑铃降至头后。
在底部停顿，然后收缩肱三头肌将手臂伸回起始位置。
重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-supinated-triceps-extension-one-arm', '哑铃过头臂屈伸（单手）', 'supinated triceps extension (one arm)', 'arms', 'cable', 1, 2, '将单把手连接到高位滑轮，背对器械站立。
一只手以反握（掌心向上）握住把手。
远离器械站立，将肘部举过头顶。
向下向前伸直前臂，直至手臂完全伸展。
缓慢回到起始位置，重复至目标次数后换臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-hammer-to-biceps-curl', '哑铃锤式接二头弯举', 'dumbbell hammer to biceps curl', 'arms', 'dumbbell', 1, 2, '双脚与肩同宽站立，双手各持一只哑铃，采用中立握法。
掌心相对将哑铃向上弯举，做锤式弯举。
在锤式弯举顶端将掌心旋转朝上，继续做标准肱二头肌弯举。
在最高点收紧肱二头肌，然后反向旋转并放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-concentration-biceps-curl', '哑铃集中弯举', 'dumbbell concentration curl', 'arms', 'dumbbell', 0, 1, '坐在长凳上，双脚平放地面，一手持哑铃。
将上臂后侧贴靠大腿内侧。
向上弯举哑铃至肩部，在顶端集中挤压肱二头肌。
缓慢将哑铃放回起始位置。
完成目标次数后换另一侧手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-landmine-press-single-arm', '地雷杆推肩', 'landmine press (single arm)', 'arms', 'barbell', 1, 2, '将杠铃一端固定在地雷架附件中或楔入墙角。
面向杠铃站立，单手在肩部高度握住自由端。
前后错步站立以保持平衡，收紧核心。
以弧形轨迹向上向前推杠铃，直至手臂完全伸直。
缓慢将杠铃放回起始位置并重复，然后换臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-triceps-dip-machine', '坐姿三头下压机', 'seated triceps dip machine', 'arms', 'machine', 1, 1, '坐在三头肌下压机上，调整座椅高度使把手位于胸部高度。
握住把手，双臂屈肘呈90度。
向下按压把手，伸直肘部直至双臂完全伸直。
在动作底部稍作停顿，收紧三头肌。
缓慢让把手回到起始位置。
重复完成目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-overhead-dumbbell-extension', '坐姿哑铃三头肌伸展', 'seated overhead dumbbell extension', 'arms', 'dumbbell', 1, 1, '坐在有靠背支撑的训练凳上，双手将一只哑铃举过头顶。
双掌托住上层配重片握住哑铃。
保持上臂不动、肘部朝前，将哑铃下放至头后。
在动作底部稍作停顿，感受肱三头肌的拉伸。
将哑铃推回头顶起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-concentration-bicep-curl', '坐姿哑铃弯举', 'seated dumbbell curl', 'arms', 'dumbbell', 0, 1, '坐在长凳上，双脚平放地面，一手持哑铃。
将上臂后侧靠在大腿内侧。
将哑铃向上弯举至肩部，顶部专注挤压肱二头肌。
缓慢将哑铃放回起始位置。
完成目标次数后换臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-chair-punch', '坐姿椅上出拳', 'seated chair punch', 'arms', 'bodyweight', 1, 1, '端坐椅上，核心收紧，双脚平放地面。
双手握拳，置于胸部高度。
一侧手臂有控制地向前出拳。
收回该臂，立即伸出另一侧手臂。
双臂交替快速出拳，持续目标时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-arm-stretch-chair', '坐姿椅上手臂拉伸', 'seated arm stretch chair', 'arms', 'bodyweight', 1, 1, '坐在椅子上，坐直，双脚平放地面。
一只手臂举过头顶，手放在脑后。
用另一只手抓住抬起手臂的肘部，轻轻向头部方向拉。
保持拉伸20-30秒，感受三头肌深度拉伸。
放松，换另一只手臂重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-concentration-curl-seated', '坐姿集中弯举', 'concentration curl (seated)', 'arms', 'dumbbell', 0, 1, '坐在长凳上，双脚平放地面，一手持哑铃。
将上臂后侧靠在大腿内侧以支撑。
收缩肱二头肌，将哑铃向上弯举至肩部。
在动作顶端稍停并挤压肱二头肌。
缓慢将哑铃放回起始位置并重复，然后换另一侧手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wide-grip-barbell-curl', '宽握杠铃弯举', 'wide grip barbell curl', 'arms', 'barbell', 1, 2, '双手正握杠铃，握距宽于肩宽，站立持铃。
让杠铃自然下垂于大腿前方，手臂伸直。
保持肘部固定，将杠铃向上弯举至肩部方向。
在顶端稍作停顿，充分收缩肱二头肌。
缓慢将杠铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wide-dumbbell-push-up', '宽距哑铃俯卧撑', 'wide dumbbell push up', 'arms', 'dumbbell', 1, 2, '将两只哑铃放在地上，间距宽于肩，握住每个把手。
呈俯卧撑姿势，双臂完全伸直，双手握住哑铃。
弯曲肘部将胸部降向哑铃之间的地面。
通过哑铃发力伸直手臂，回到起始位置。
按目标次数重复，全程保持身体呈一条直线。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-skullcrusher', '屈腿哑铃仰卧臂屈伸', 'dumbbell skullcrusher', 'arms', 'dumbbell', 1, 2, '平躺在长凳上，双手各持一只哑铃，手臂伸直于胸部正上方。
保持上臂固定并垂直于地面。
缓慢弯曲肘部，将哑铃下放至头部两侧。
在哑铃接近太阳穴前稍作停顿，然后伸直手臂回到起始位置。
重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-single-arm-dumbbell-triceps', '平板支撑单臂哑铃臂屈伸', 'plank single arm dumbbell triceps', 'arms', 'dumbbell', 1, 2, '从高平板姿势开始，一只手撑在哑铃上，另一只手平放地面。
从平板姿势做三头肌后踢，将持哑铃手臂的肘部弯曲至90度。
伸直肘部将哑铃向后伸展，直到手臂与地面平行。
慢慢将哑铃回到弯曲位置。
一侧完成所有次数后换手。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bench-dips-high', '平板臂屈伸-高难度', 'Bench Dips High', 'arms', 'bodyweight', 1, 2, '双手放在身后长凳上，双脚抬高放在前方等高或更高的平面上。
身体悬空于两个平面之间，屈肘将髋部向地面下降。
下降至上臂大致与地面平行。
手掌发力伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lunges-alternate-biceps-curl', '弓步交替弯举', 'lunges alternate biceps curl', 'arms', 'bodyweight', 1, 1, '双脚与髋同宽站立，双手各持一只哑铃放在身体两侧。
一只脚向前迈出成弓步，后膝向地面降低。
下蹲成弓步时，将两只哑铃弯举向肩部。
前脚发力回到站立姿势，同时放下哑铃。
换另一条腿重复，两侧交替，按所需次数进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-overhead-triceps-extension', '弹力带-过头臂屈伸', 'resistance band overhead triceps extension', 'arms', 'band', 1, 1, '呈半跪姿，一侧膝盖着地，将弹力带一端固定在该跪地腿下方。
双手握住弹力带另一端，双臂完全伸直举过头顶。
保持上臂固定并贴近头部，弯曲肘部将双手缓慢下放至头后。
在动作底部稍作停顿。
伸直肘部将双臂回到起始位置，同时挤压肱三头肌。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-band-pushups', '弹力带俯卧撑', 'band pushups', 'arms', 'band', 1, 2, '将阻力带绕过上背部，双手各握一端，手掌平放地面。
呈标准俯卧撑姿势，双手略宽于肩。
屈肘将胸部下放至接近地面，身体保持一条直线。
手掌发力伸臂返回起始位置，对抗阻力带阻力。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-biceps-curl', '弹力带弯举', 'banded biceps curl', 'arms', 'band', 1, 1, '双脚与肩同宽踩在阻力带中央站立。
双手各握阻力带一端，掌心向上握法，双臂自然垂于体侧。
肘部紧贴躯干，双手向上弯举至肩部。
在动作顶端夹紧肱二头肌。
缓慢将双手还原至起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-biceps-curl', '弹力绳-站姿二头弯举', 'resistance band biceps curl', 'arms', 'band', 1, 1, '双脚与肩同宽踩住弹力带中间，双手各握一端。
起始时双臂在体侧完全伸直，掌心朝前。
屈肘将两端向上弯举至肩部。
在顶部停顿，挤压肱二头肌。
缓慢将手臂放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-fast-punches-shadow-boxing', '快速出拳（空击）', 'Fast Punches (Shadow Boxing)', 'arms', 'bodyweight', 1, 1, '双脚与肩同宽站立，双手抬至脸旁防守位置。
双手快速交替向前出拳，出拳时旋转手腕使掌心朝下。
保持核心收紧、肩部放松，维持快速出拳节奏。
有节奏地呼吸，脚步保持轻盈。
按目标次数或时间持续进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-fast-punches-shadow-boxing-advanced', '快速出拳（空击）进阶', 'Fast Punches (Shadow Boxing) Advanced', 'arms', 'bodyweight', 1, 2, '以拳击站姿站立，双手抬起，膝盖微屈。
开始快速交替出拳，同时移动脚步，向前、向后和侧向踏步。
以最大速度组合刺拳、直拳和勾拳。
收紧核心，每次出拳时旋转髋部。
持续目标时间或回合数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-battle-rope-alternate-slam-in-out', '战绳交替砸地内外', 'battle rope alternate slam in out', 'arms', 'other', 1, 2, '运动站姿，双手各握战绳一端。
一臂举过头顶向下砸绳至地面，同时该侧脚向外迈步。
立即换另一臂上举下砸，另一侧脚向外迈步。
连续交替、保持节奏，维持稳定的运动基础站姿。
按目标时长或次数持续进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-suitcase-carry', '手提箱行走', 'suitcase carry', 'arms', 'dumbbell', 1, 2, '一只手握住重哑铃垂于体侧，手臂完全伸直。
收紧核心，抵抗向负重侧倾斜。
控制步伐向前行走，保持躯干直立、双肩水平。
保持握力，避免向远离负重方向倾斜。
完成目标距离或时间后换手。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wrist-extension-stretch-fingers-down', '手腕伸展拉伸（手指向下）', 'Wrist Extension Stretch Fingers Down', 'arms', 'bodyweight', 0, 1, '一只手臂向前伸直，掌心朝下。
用另一只手轻轻将手指向下、朝身体方向按压。
当前臂上侧感到拉伸时保持。
保持20-30秒。
换手重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wrist-circle', '手腕环绕', 'wrist circle', 'arms', 'bodyweight', 0, 1, '双臂向前伸直，与肩同高。
双手握拳，开始缓慢地做完整的绕腕动作。
向一个方向绕指定次数，然后反方向绕。
保持动作流畅可控。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-arm-stretch-version-1', '手臂拉伸1', 'arm stretch version 1', 'arms', 'bodyweight', 1, 1, '直立，双脚与肩同宽。
将一只手臂举过头顶，弯曲肘部使手伸向对侧肩胛骨。
用另一只手轻轻向下按压抬起的手肘，加深拉伸。
保持20-30秒，然后换手臂。
两侧交替重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-arm-stretch-version-2', '手臂拉伸2', 'arm stretch version 2', 'arms', 'bodyweight', 1, 1, '直立，双脚与肩同宽。
将一只手臂在肩高处横过胸前伸直。
用对侧手或前臂将伸直的手臂向胸前按压。
保持拉伸20-30秒，感受肩部的牵拉感。
换手臂，在另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-boxing-beginners', '拳击入门', 'Boxing Beginners', 'arms', 'bodyweight', 1, 1, '双脚与肩同宽站立，膝盖微屈，双手抬至面部附近的防守位置。
前手向前伸直打出刺拳，完全伸展时拳心朝下。
收回刺拳，后手打出直拳，髋部和肩部转入出拳。
以可控节奏持续交替刺拳和直拳。
按目标次数或时间重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-skull-crusher', '杠铃仰卧臂屈伸_颅骨粉碎者', 'barbell skull crusher', 'arms', 'barbell', 1, 2, '平躺在长凳上，正握杠铃，双臂伸直于胸部上方。
整个动作过程中上臂保持垂直于地面且固定不动。
缓慢弯曲肘部，将杠铃下降至额头或额头正上方。
在杠铃接近头部前稍作停顿，然后伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-curl', '杠铃弯举', 'barbell curl', 'arms', 'barbell', 1, 1, '双脚与肩同宽站立，以反握握住杠铃，双手与肩同宽。
让杠铃在身前自然下垂，手臂伸直，肘部贴近躯干。
弯曲肘部将杠铃向上弯举至胸前，保持上臂不动。
在动作顶部收紧肱二头肌。
缓慢将杠铃下放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-curl-standard', '杠铃标准弯举', 'barbell curl standard', 'arms', 'barbell', 1, 1, '直立站立，以反握握住杠铃，双手与肩同宽。
保持肘部贴近躯干，上臂不动。
收缩肱二头肌将杠铃向上弯举，直至杠铃到达肩部高度。
在动作顶部停顿并收紧肱二头肌。
缓慢将杠铃下放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-curl-narrow-grip', '杠铃窄握弯举', 'barbell curl narrow grip', 'arms', 'barbell', 1, 2, '双脚与肩同宽站立，以窄于肩宽的反握握住杠铃。
双臂完全伸直，将杠铃保持在身前大腿处。
保持肘部内收，将杠铃向上弯举至胸前。
在顶部停顿并收紧肱二头肌。
缓慢将杠铃下放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-hold', '杠铃静力握持', 'barbell hold', 'arms', 'barbell', 1, 1, '双脚与肩同宽站立，正握杠铃置于身体两侧。
双臂自然下垂，手指完全伸展握住杠铃。
尽可能用力握紧杠铃，保持所需时间。
专注于维持握力，手臂不要弯曲。
控制杠铃放下，休息后重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bench-dips', '椅子双臂臂屈伸', 'Bench Dips', 'arms', 'bodyweight', 1, 1, '坐在稳固长凳或椅子边缘，双手抓住髋部两侧边缘。
将髋部滑离长凳，双腿向前伸出，脚跟踩地。
屈肘将身体向地面下降，直到上臂与地面平行。
手掌发力伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chair-arm-stretch', '椅子手臂拉伸', 'chair arm stretch', 'arms', 'bodyweight', 1, 1, '坐在椅子上，保持上身直立，双脚平放地面。
将一侧手臂举过头顶并弯曲肘部，让手落到头后。
用另一只手轻压肘部，以加深拉伸。
保持拉伸20–30秒，感受肱三头肌和肩部的延展。
放松后换另一侧手臂重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-towel-biceps-curl', '毛巾二头弯举', 'Towel Biceps Curl', 'arms', 'bodyweight', 1, 1, '坐在稳固的椅子上，将卷起的毛巾放在一侧大腿下方。
用同侧手握住毛巾两端。
对抗毛巾阻力向上弯举，收紧肱二头肌。
缓慢回到起始位置。
按所需次数重复后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-arm-butterfly-with-bottle-stretch', '水瓶蝴蝶臂拉伸', 'arm butterfly with bottle stretch', 'arms', 'bodyweight', 1, 1, '双脚与肩同宽站立，双手各持一瓶水置于体侧。
双臂向两侧抬起至肩高，掌心向下。
双臂缓慢向前，在胸前以蝴蝶式交叉。
双臂向两侧打开，回到起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-tate-press', '泰特推举', 'tate press', 'arms', 'dumbbell', 1, 2, '平躺在长凳上，双手各持一个哑铃，手臂在胸前伸直。
肘部向两侧打开，屈肘将哑铃下放至胸前。
下放哑铃直到触及胸部，肘部大幅外展。
伸肘将哑铃推回起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-preacher-curl-machine', '牧师器弯举', 'preacher curl machine', 'arms', 'machine', 0, 1, '坐在牧师椅弯举机上，调整座椅使上臂平放在斜垫上。
以旋后握法握住把手，手臂完全伸直。
屈肘将把手向上弯举至肩部方向。
在顶部停顿并挤压肱二头肌。
缓慢将把手放回完全伸直的起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-straight-barbell-curl', '直杆杠铃弯举', 'straight barbell curl', 'arms', 'barbell', 1, 1, '站立，以肩宽反握直杆杠铃。
让杠铃在手臂伸直状态下垂于大腿前方。
将杠铃向上弯举至胸前，保持肘部固定。
在动作顶端停顿并挤压肱二头肌。
缓慢下放杠铃至起始位置。
重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-pushdown-cable-straight-bar', '直杆绳索下压', 'triceps pushdown (cable - straight bar)', 'arms', 'cable', 0, 1, '将直杆连接到绳索器械的高滑轮上，面向器械站立。
双手采用正握法握住直杆，与肩同宽，肘部贴近身体两侧。
伸直手臂将直杆向下推，直到手臂完全伸直。
在底部停顿并挤压三头肌。
缓慢让直杆回到起始位置，重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-curl-straight-bar', '直杆绳索弯举', 'cable curl (straight bar)', 'arms', 'cable', 1, 1, '将直杆连接到绳索器械的低位滑轮，面向器械站立。
以反手握法握住直杆，双手与肩同宽，肘部保持在身体两侧。
收缩肱二头肌将直杆向上弯举，直至前臂与地面平行。
在顶部停顿并挤压肱二头肌，然后缓慢将直杆放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-skull-crushers-ez-bar', '碎颅者', 'skull crushers (ez bar)', 'arms', 'barbell', 0, 2, '平躺在长凳上，正握ez曲杆，双臂伸直于胸部正上方。
保持上臂垂直、肘部朝天花板，缓慢将杆下放至额头方向。
在额头上方稍作停顿，然后收缩三头肌将手臂伸回起始位置。
全程保持肘部内收，避免向外张开。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-prayer-stretch', '祈祷式拉伸', 'Prayer Stretch', 'arms', 'bodyweight', 0, 1, '双手在胸前合十呈祈祷姿势。
保持手掌相压，缓慢将双手向腰部下移。
当感觉前臂和手腕有张力时保持拉伸。
保持20-30秒，然后放松。
按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-incline-push-up-close', '窄距上斜俯卧撑', 'Incline Push-Up – Close', 'arms', 'bodyweight', 1, 1, '双手并拢放在较高的平面上，双脚后撤形成一条直线斜板身体姿势。
整个动作过程中保持肘部贴近身体两侧。
弯曲肘部将胸部向平面方向下放。
推回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-close-push-ups-advanced-nose-touch-on-floor', '窄距俯卧撑进阶（鼻触地）', 'Close Push Ups Advanced(Nose touch On Floor)', 'arms', 'bodyweight', 1, 3, '从俯卧撑姿势开始，双手靠拢放在胸部正下方。
整个动作过程中保持肘部紧贴身体两侧。
将身体完全下放，直到鼻子接触地面。
通过手掌爆发发力推回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-single-arm-overhead-extension', '站姿单臂绳索肱三头肌伸展', 'standing single arm overhead extension', 'arms', 'dumbbell', 1, 1, '双脚与肩同宽站立，一手持哑铃。
将哑铃推举过头顶，然后屈肘将其降至头后。
保持上臂固定并靠近头部。
伸直手臂回到头顶起始位置。
在顶端停顿并收紧肱三头肌。
完成目标次数后换臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-supinated-bicep-curl', '站姿反握杠铃弯举', 'standing supinated bicep curl', 'arms', 'barbell', 1, 1, '双脚与肩同宽站立，以完全旋后的握法握住杠铃，掌心朝上。
让杠铃在手臂伸直的状态下悬于髋部前方。
将杠铃向上弯举至肩部方向，保持肘部贴近身体两侧。
在顶部停顿并挤压肱二头肌。
以受控的方式将杠铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-barbell-extension', '站姿杠铃臂屈伸', 'standing barbell extension', 'arms', 'barbell', 1, 2, '双脚与肩同宽站立，正握杠铃置于上胸位置。
收紧核心，将杠铃垂直向上推举至手臂完全伸直。
在动作顶端稍作停顿。
缓慢有控制地将杠铃放回上胸起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-barbell-overhead-extension', '站姿杠铃颈后臂屈伸', 'standing barbell overhead extension', 'arms', 'barbell', 1, 2, '双脚与肩同宽站立，双手以略窄于肩宽的握距将杠铃推举过头顶。
保持核心收紧，上臂垂直于地面。
缓慢屈肘将杠铃下放至头后。
在底部停顿，感受肱三头肌的拉伸。
伸直手臂回到过头起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-wood-chop', '站姿绳索转体', 'cable wood chop', 'arms', 'cable', 1, 2, '将单手把手连接到绳索器械的高位滑轮，侧身站在器械旁。
双手握住把手，双脚与肩同宽站立。
以一次横扫动作，将把手斜向下拉过身体，拉向对侧髋部，同时旋转躯干。
控制动作，将把手回到起始位置。
完成一侧的所有次数后再换边。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-cable-concentration-curls', '站姿绳索集中弯举', 'standing cable concentration curls', 'arms', 'cable', 0, 2, '将单把手连接至绳索器械低位滑轮。
站在器械旁，单手握住把手，手臂完全伸展横过身体。
将把手上弯至肩部，保持上臂固定不动。
在顶端停顿并挤压肱二头肌。
缓慢将把手放回起始位置。
完成目标次数后换手。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-wrist-flexor-stretch', '站姿腕屈肌拉伸', 'Standing Wrist Flexor Stretch', 'arms', 'bodyweight', 0, 1, '将一只手臂向前伸直，掌心朝上。
用另一只手轻轻将手指向下、向身体方向拉。
当前臂内侧和手腕感到紧张时保持拉伸。
保持20-30秒。
换手重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-triceps-pushdown-v-bar-attachment', '绳索三头下压（V型把手）', 'cable triceps pushdown (v-bar attachment)', 'arms', 'cable', 1, 1, '将V形杆连接到绳索器械的高滑轮，面向器械站立。
以正握握住V形杆，肘部贴近身体两侧。
保持上臂不动，将杆向下推，直到手臂完全伸展。
在底部稍作停顿，收紧肱三头肌。
缓慢让杆回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-tricep-kickback', '绳索三头后踢', 'cable tricep kickback', 'arms', 'cable', 0, 1, '将单手把手连接到绳索器械的低滑轮。
在髋部向前俯身，直到躯干几乎与地面平行，并握住把手。
保持上臂固定在体侧，伸展肘部将把手笔直向后踢出。
手臂完全伸展时稍作停顿，收紧肱三头肌。
缓慢弯曲肘部回到起始位置。
完成目标次数后换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-triceps-pushdown', '绳索臂屈伸', 'triceps pushdown', 'arms', 'cable', 1, 1, '将直杆或绳索连接至绳索器械的高位滑轮。
面朝器械站立，正握把手，肘部置于身体两侧。
伸直肘部向下推杆或绳索，直至手臂完全伸直。
在底部稍作停顿，收紧肱三头肌。
缓慢让重量回升至起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-overhead-triceps-extension', '绳索过头臂屈伸', 'cable overhead triceps extension', 'arms', 'cable', 1, 2, '将绳索连接到绳索器械的低滑轮，背对器械站立。
双手将绳索举过头顶，肘部弯曲并朝向天花板。
保持肘部不动，将手臂完全向上伸展。
在动作顶端稍作停顿，收紧肱三头肌。
缓慢将绳索放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-spider-curl', '蜘蛛弯举', 'dumbbell spider curl', 'arms', 'dumbbell', 0, 2, '将上斜凳调至约45度，面朝下趴下，胸部贴紧靠垫。
双手各持一只哑铃，手臂自然下垂，掌心朝前。
收缩肱二头肌将哑铃向上弯举，保持上臂垂直于地面。
在动作顶端停顿并挤压肱二头肌。
缓慢将哑铃放回起始位置，重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-kneeling-overhead-tricep-extension', '跪姿肱三头肌伸展', 'kneeling overhead tricep extension', 'arms', 'band', 1, 2, '单膝跪地，将阻力带固定在着地膝盖下方。
双手握住阻力带另一端，将手臂举过头顶。
保持上臂不动，弯曲肘部将双手降至头后。
完全伸直手臂举过头顶回到起始位置，收紧三头肌。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-kneeling-hammer-curl-to-hammer-shoulder-press', '跪姿锤式弯举接锤式肩推', 'kneeling hammer curl to hammer shoulder press', 'arms', 'dumbbell', 1, 1, '双膝跪地，双手各持哑铃，采用中立握法，双臂垂于体侧。
以锤式弯举动作将哑铃弯举至肩高。
将哑铃推举过头顶直至双臂完全伸直。
将哑铃放回肩高，再降至起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-diamond-push-up', '钻石俯卧撑', 'diamond push up', 'arms', 'bodyweight', 1, 2, '从平板支撑姿势开始，双手在胸骨下方合拢，拇指和食指相触形成菱形。
整个动作中肘部贴近身体，收紧核心。
有控制地将胸部朝双手方向下压，直到几乎触地。
在底部稍作停顿，然后推回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-diamond-push-ups-close', '钻石窄距俯卧撑', 'Diamond Push Ups Close', 'arms', 'bodyweight', 1, 2, '从俯卧撑姿势开始，双手靠得很近，手指几乎相触，位于胸部正下方。
用食指和拇指形成窄菱形。
将胸部朝双手方向下压，肘部朝后。
推回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-hammer-curl', '锤式弯举', 'dumbbell hammer curl', 'arms', 'dumbbell', 1, 1, '直立站立，双手各持一只哑铃，采用中立握法，掌心朝向躯干。
肘部贴近身体两侧，上臂保持不动。
保持中立握法将哑铃向上弯举至肩部高度。
在顶端稍作停顿，收紧肱二头肌和前臂。
缓慢将哑铃放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-concentration-curl', '集中弯举', 'concentration curl', 'arms', 'dumbbell', 0, 1, '坐在长凳上并稍向前倾，将右肘靠在右大腿内侧。
右手持哑铃，手臂完全伸直。
通过弯曲肘部将哑铃向上弯举至肩部。
在顶部稍作停顿并充分收紧肱二头肌。
缓慢将哑铃回到起始位置。
完成目标次数后换另一侧手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-45-degree-hyperextension-machine', '45度山羊挺身机', '45-degree hyperextension machine', 'back', 'machine', 1, 1, '俯卧于45度山羊挺身器上，髋部置于垫子上方，双脚固定在脚垫下。
双臂交叉于胸前或置于脑后。
以髋部为轴，将躯干向下降低。
在最低点稍作停顿，感受下背部的拉伸。
收缩下背部和臀肌，将躯干抬回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-t-bar-row', 'T杆划船', 't-bar row', 'back', 'barbell', 1, 2, '将杠铃一端装入地雷管附件，跨站在杠铃两侧。
用双手握住杠铃末端，可使用中立握把手或托住杠铃片。
屈髋使躯干前倾约45度，保持背部平直。
肘部向后拉，将杠铃向胸部划起并挤压肩胛骨。
缓慢将杠铃放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-t-bar-deadlift-to-row', 'T杠硬拉划船', 't-bar deadlift to row', 'back', 'barbell', 1, 3, '在T杠划船机上加载重量，双脚与髋同宽站在杠上。
屈髋俯身握住把手，保持背部平直。
脚跟发力站直完成硬拉。
在顶部将杠铃向胸部划起，肘部向后拉。
将杠铃放回髋部方向，然后回到硬拉起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reach-to-w', 'W字后伸', 'reach to w', 'back', 'bodyweight', 1, 1, '跪在地上，躯干直立，双手在胸前合拢。
双臂向前伸直，向前延伸，上背部略微弓起。
将双手拉回胸前起始位置。
双臂向两侧打开，弯曲肘部形成“W”形，同时夹紧肩胛骨。
双手回到胸前合拢。
继续交替进行前伸和“W”打开至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-y-t-w-beginners', 'YTW入门', 'y-t-w beginners', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，髋部微微前倾。
双臂向上呈Y形伸展，肩胛骨向内收紧。
放下双臂，在肩高处呈T形伸展。
放下双臂，屈肘呈W形。
回到起始位置，按目标次数重复Y-T-W序列。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-y-t-w-hand-leg-raise', 'YTW对侧手脚抬起', 'y t w hand leg raise', 'back', 'bodyweight', 1, 2, '俯卧在地面上，双臂和双腿伸展。
同时将双臂抬成Y形，并将对侧腿抬离地面。
双臂向两侧伸直转为T形，再屈肘转为W形。
放回起始位置，重复该序列。
按目标次数继续。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-y-t-w-hand-raise', 'YTW手臂抬起', 'y t w hand raise', 'back', 'bodyweight', 1, 1, '俯卧在地面上，额头贴地，双臂过头伸展。
将双臂抬成Y形，肩胛骨向内收紧。
放下双臂，再抬成T形，然后屈肘呈W形。
每个姿势后放下双臂再进入下一个姿势。
按目标次数完成全部三个姿势。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-downward-facing-dog-adho-mukha-svanasana', '下犬式', 'downward-facing dog (adho mukha svanasana)', 'back', 'bodyweight', 1, 1, '从双手双膝的桌面位开始，手腕位于肩下，膝盖位于髋下。
脚趾扣地，呼气时将臀部抬向天花板。
尽量伸直手臂和双腿，身体形成倒V形。
双手用力压垫，手指大幅张开，肩胛骨沿背部向下收。
保持30-60秒，交替踩脚跟以拉伸小腿，然后回到桌面位。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-downward-dog-upper-back-stretch', '下犬式上背拉伸', 'downward dog upper back stretch', 'back', 'bodyweight', 1, 1, '从四点跪姿的桌面位开始。
脚趾扣地，将臀部向上向后抬起，形成倒V形。
双手用力压地，将胸口推向大腿。
保持拉伸，专注拉长上背部20-30秒。
缓慢回到起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cross-lat-pulldown', '交叉高位下拉', 'cross lat pulldown', 'back', 'cable', 1, 2, '在绳索交叉训练器两侧的高位滑轮上各连接一个单手把手。
跪或站在中间，双手各握一个把手，手臂向上伸直。
同时将两个把手向下拉向身体两侧，肘部朝髋部方向驱动。
在动作底部挤压背阔肌。
缓慢将把手送回头顶并重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-leg-bent-hold-back-stretch', '仰卧屈腿抱膝背部拉伸', 'lying leg bent hold back stretch', 'back', 'bodyweight', 1, 1, '仰卧平躺，双膝弯曲，双脚平放于地面。
双膝向胸部靠拢，双臂环抱小腿。
双膝贴近胸部保持，如舒适可轻轻左右摇摆。
保持拉伸姿势20–30秒。
放松后重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-pullover', '仰卧屈臂上抬', 'dumbbell pullover', 'back', 'dumbbell', 1, 2, '平躺在凳子上，双手共持一只哑铃，手臂伸直置于头顶。
肘部微屈，以宽弧线将哑铃向头后下放至接近地面。
在动作底部感受背阔肌和胸部的拉伸。
沿相同弧线将哑铃拉回胸部上方的起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-back-and-hips-stretch', '仰卧背髋拉伸', 'lying back and hips stretch', 'back', 'bodyweight', 1, 1, '仰卧，双腿伸直。
双膝抱向胸前，双臂环抱膝盖。
轻轻将膝盖拉向胸口，感受下背部和髋部的拉伸。
保持20–30秒，深呼吸。
放松，缓慢将双腿放回地面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-supine-spinal-stretch', '仰卧脊柱拉伸', 'supine spinal stretch', 'back', 'bodyweight', 1, 1, '仰卧平躺，双臂向两侧伸展成T形。
弯曲右膝，将其拉向胸部。
呼气，引导右膝越过身体向左侧下放至地面。
目光转向右侧，双肩保持平贴垫面。
保持扭转30-60秒，然后将膝盖回到中间，换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-conventional-deadlift', '传统硬拉', 'conventional deadlift', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，杠铃位于脚中部上方。
屈髋俯身，在双腿外侧以正握或正反握握住杠铃。
收紧核心，保持背部平直，蹬地开始提起。
杠铃过膝时向前送髋，完成站立姿势。
在顶端稍停，髋部完全伸展。
控制杠铃放回地面并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lateral-bear-crawl', '侧向熊爬', 'lateral bear crawl', 'back', 'bodyweight', 1, 2, '从熊撑姿势开始，四点支撑，膝盖悬停在地面上方。
收紧核心，右手和右脚同时向外迈步侧向移动。
左手和左脚跟随，保持身体宽度。
继续侧向爬行至目标距离，然后换方向。
整个动作过程中保持髋部低、背部平直。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chest-supported-dumbbell-rows', '俯卧哑铃划船', 'chest supported dumbbell rows', 'back', 'dumbbell', 1, 1, '将上斜凳调至30-45度，俯卧，胸部贴紧靠垫。
双手各持一只哑铃，手臂自然下垂。
肘部朝天花板方向发力，将两只哑铃向上拉起。
在动作顶端夹紧肩胛骨。
慢慢将哑铃放回起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-prone-back-extension', '俯卧背部伸展', 'prone back extension', 'back', 'bodyweight', 1, 1, '俯卧在垫子上，双腿向后伸直，双臂向前伸直。
收紧臀部和下背部，将胸部、手臂和双腿稍微抬离地面。保持颈部中立。
保持抬起的身体姿势，缓慢将伸直的手臂向两侧扫开并向下扫向髋部。
双手到达身体两侧时，挤压肩胛骨。
缓慢反向运动，将手臂向前扫回起始位置。
保持身体抬起，按目标次数重复手臂扫动。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bent-over-dumbbell-row', '俯身哑铃划船', 'bent over dumbbell row', 'back', 'dumbbell', 1, 2, '双脚与肩同宽站立，双手各持一只哑铃。
髋部前屈，使躯干接近与地面平行，保持脊柱中立。
让哑铃在胸部下方自然下垂至手臂伸直。
肘部向后发力，同时将两只哑铃拉向髋部。
在收缩位置停顿，收紧背阔肌。
缓慢将哑铃放回起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bent-over-barbell-row', '俯身杠铃划船', 'bent over barbell row', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，正握杠铃，握距略宽于肩。
髋部前屈，直到躯干接近与地面平行，保持脊柱中立。
让杠铃在胸部下方自然下垂至手臂伸直。
肘部向上发力，将杠铃拉向下肋部。
在顶端停顿，收紧肩胛骨。
缓慢将杠铃放回起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-exercise-ball-reverse-superman', '健身球反向超人', 'exercise ball reverse superman', 'back', 'other', 1, 1, '俯卧，将髋部置于健身球上，双脚抵住墙壁或地面固定。
双手置于脑后或向前伸直。
保持核心收紧，抬起上半身并伸展背部，直至身体呈一条直线。
在顶端保持片刻，然后缓慢回到起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hex-bar-deadlift', '六角杠硬拉', 'hex bar deadlift', 'back', 'barbell', 1, 1, '站入六角杠内，双脚与髋同宽。
髋部铰链，弯曲膝盖，握住身体两侧的把手。
保持背部平直，胸部挺起，肩胛骨收紧。
通过脚跟发力站直，同时伸展髋部和膝盖。
控制下将杠铃放回地面，保持背部平直。
重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hex-bar-deadlift-to-shrug', '六角杠铃硬拉耸肩', 'hex bar deadlift to shrug', 'back', 'barbell', 1, 2, '双脚与髋同宽站入六角杠内，握住把手。
屈髋屈膝下蹲至杠铃处，保持背部平直。
脚跟发力站直，完成硬拉。
在动作顶端耸肩，将肩膀向耳朵方向抬起。
放下肩膀，然后有控制地将杠铃放回地面。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-lat-pulldown', '单手下拉', 'single arm lat pulldown', 'back', 'cable', 1, 2, '将单手把手连接到高位滑轮，坐在高位下拉器上。
一只手握住把手，手臂完全向上伸展。
肘部向髋部方向发力，将把手向下拉向肩部。
在动作底部挤压背阔肌。
缓慢让把手回到头顶位置，重复目标次数后换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-king-pigeon-pose-rajakapotasana', '单腿鸽王式', 'king pigeon pose (rajakapotasana)', 'back', 'bodyweight', 1, 3, '从鸽子式开始，右小腿向前，左腿向后伸展。
弯曲左膝，左手向后伸抓住左脚。
右臂举过头顶，也向后伸抓住左脚。
胸口向上打开，脚向头部方向轻压，缓慢加深后弯。
保持20-30秒，然后小心松开脚，换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-eka-hasta-vyagrasana', '单臂伸展式', 'eka hasta vyagrasana', 'back', 'bodyweight', 1, 2, '从手膝着地的桌面姿势开始。
右腿向后伸直并屈膝，将右脚抬向天花板。
左手向后伸抓住右脚，形成后弯。
用右臂和左膝保持平衡，同时向上打开胸腔。
保持20-30秒，然后放开并换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-row', '单臂划船', 'single arm row', 'back', 'dumbbell', 1, 1, '一侧膝盖和同侧手撑在长凳上，另一只手持哑铃。
保持背部平直，与地面平行。
将哑铃拉向髋部，肘部笔直向后发力。
在动作顶部挤压背阔肌。
缓慢将哑铃放回起始位置。
完成目标次数后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-straight-arm-cable-pulldown', '单臂直臂绳索下拉', 'single arm straight arm cable pulldown', 'back', 'cable', 1, 1, '将单手把手连接到绳索器械的高位滑轮上。
面向器械站立，用一只手以中立握法握住把手。
身体微微前倾，手臂举过头顶伸展，肘部保持微屈。
保持手臂近乎伸直，通过收缩背阔肌将把手沿弧线向下拉向髋部。
在底部稍作停顿，然后缓慢控制回到起始位置。
一侧完成所有次数后再换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-cable-pull-down', '单臂绳索下拉', 'single arm cable pull down', 'back', 'cable', 1, 1, '将单手把手连接到高位下拉器的高位滑轮上。
坐下，大腿固定在垫子下方，一只手握住把手，手臂完全伸展。
将把手向下拉向肩部，肘部向髋部方向发力。
在动作底部稍作停顿。
缓慢将把手回到起始位置。
完成目标次数后换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reverse-bridge-pose-ii', '反向桥式二', 'reverse bridge pose ii', 'back', 'bodyweight', 1, 1, '坐在地面上，双腿伸直，双手放在臀部后方地面上，手指朝后。
用手掌和脚跟发力将臀部尽可能抬高离开地面。
夹紧臀肌，头部轻轻后仰。
保持该姿势20-30秒。
缓慢将臀部放回地面并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chin-up', '反手引体向上', 'chin up', 'back', 'bodyweight', 1, 2, '以反手握法握住引体向上杆，双手与肩同宽。
悬垂，双臂完全伸展，身体放松。
收紧核心，将肩胛骨向下向后收。
向上拉起身体，直到下巴超过横杆，胸部领先。
有控制地慢慢降回起始位置，按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chin-up-leg-folded', '反手引体向上屈腿', 'chin up leg folded', 'back', 'bodyweight', 1, 2, '以反手握法悬挂在引体向上杆上，双手与肩同宽。
交叉脚踝并弯曲膝盖，将双腿折叠到身后。
收紧核心，向上拉起身体，直到下巴超过横杆。
在顶部停顿，挤压背阔肌和肱二头肌。
慢慢降回悬挂位置，按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reverse-prayer-forward-fold', '反祈祷前屈', 'Reverse Prayer Forward Fold', 'back', 'bodyweight', 1, 2, '双脚与髋同宽站立，双手在背后做反祈祷姿势。
从髋部向前折叠，保持背部平直、颈部中立。
将躯干向地面下压，加深背部和手腕的拉伸。
保持20-30秒，均匀呼吸。
缓慢起身回到站立，重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-back-row-smith-machine', '史密斯机后拉划船', 'back row smith machine', 'back', 'machine', 1, 1, '将史密斯机横杆调至约髋部高度，面向横杆站立。
以略宽于肩的正握握住横杆。
双脚向前走并向后倾斜，使身体呈角度悬垂，手臂完全伸展。
通过肘部向后发力将胸部拉向横杆，夹紧肩胛骨。
在动作顶端停顿，然后缓慢降回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-reach-back-thoracic-bridge', '后仰胸椎桥', 'reach back - thoracic bridge', 'back', 'bodyweight', 1, 1, '从手膝支撑的桌面姿势开始。
一只手放在头后，肘部朝外。
旋转躯干，将该肘部朝手臂与膝盖之间的地面靠近。
然后向反方向旋转，打开胸腔，将该肘部朝天花板延伸。
重复至目标次数后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-rear-delt-dumbbell-fly', '哑铃俯身后束飞鸟', 'rear delt dumbbell fly', 'back', 'dumbbell', 1, 1, '每只手握一只哑铃，屈髋前倾直到躯干几乎与地面平行。
让哑铃垂在胸部下方，掌心相对。
肘部微屈，双臂向两侧抬起直到与肩同高。
在顶端停顿，挤压肩胛骨。
缓慢将哑铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-bent-over-row', '哑铃划船', 'dumbbell bent-over row', 'back', 'dumbbell', 1, 2, '双脚与肩同宽站立，双手各持哑铃，采用对握（掌心相对）。
髋部前倾，保持背部挺直、膝盖微屈。
让哑铃垂直下垂至地面开始。
将哑铃拉向腰部，肘部向后驱动，肩胛骨夹紧。
动作顶部稍停。
缓慢可控地将重量降回起始位置。
重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-renegade-row', '哑铃划船俯卧撑', 'renegade row', 'back', 'dumbbell', 1, 3, '从高平板支撑开始，每只手握一只哑铃，双手位于肩下。
双脚间距宽于髋部以保持稳定，收紧核心。
将右侧哑铃划向右髋，肘部贴近身体。
放下哑铃，在左侧重复划船。
保持平板支撑稳定，继续交替划船。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-single-arm-dumbbell-row', '哑铃划船（手扶）', 'single arm dumbbell row', 'back', 'dumbbell', 1, 1, '右膝和右手撑在长凳上，左手持哑铃。
让哑铃自然下垂于肩部正下方，手臂完全伸展。
肘部向后发力，将哑铃向上拉向左髋部。
在顶部停顿，挤压背阔肌。
缓慢将哑铃放回起始位置。
完成目标次数后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dumbbell-shrug', '哑铃耸肩', 'dumbbell shrug', 'back', 'dumbbell', 1, 1, '直立站立，双手各持哑铃垂于体侧，采用中立握法。
手臂自然下垂，双肩放松。
以可控的耸肩动作将双肩尽可能向耳朵方向抬高。
顶端短暂停顿，挤压斜方肌。
缓慢将双肩下放回起始位置，重复完成目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lat-pulldown', '器械下拉', 'lat pulldown', 'back', 'cable', 1, 1, '坐在高位下拉器上，调整大腿垫固定双腿。
以略宽于肩的正握握住横杆。
身体略微后仰，将横杆拉向上胸，肘部向髋部方向发力。
在动作底部收紧背阔肌。
缓慢可控地让横杆回到起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-prisoner-standing-upper-body-bent', '囚徒站姿上身前屈', 'Prisoner Standing Upper Body Bent', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，双手放在脑后，手指交叉。
髋部铰链前屈，降低躯干至大致与地面平行。
保持背部平直，肘部打开。
保持姿势20-30秒，感受上背部和背阔肌的拉伸。
回到站立姿势并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-landmine-barbell-deadlift', '地雷杆硬拉', 'landmine barbell deadlift', 'back', 'barbell', 1, 2, '将杠铃一端插入地雷架附件，另一端加载杠铃片。
面向加载端站立，双脚与肩同宽，屈髋握杠。
收紧核心，保持背部平直，肩胛骨向下向后收。
脚跟发力站起，同时伸展髋部和膝盖。
屈髋控制下放杠铃，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-upper-back-pull-w-squeeze', '坐姿上背W型后缩下拉', 'Seated Upper Back Pull (W-Squeeze)', 'back', 'bodyweight', 1, 1, '端坐，双脚平放地面，双臂向前伸直与肩同高。
屈肘向后拉，双臂形成W形。
在动作末端用力收紧肩胛骨。
保持收紧2-3秒，然后将双臂回到伸直位置。
重复完成目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-upper-body-bent', '坐姿上身前屈', 'seated upper body bent', 'back', 'bodyweight', 1, 1, '端坐在垫子上，双腿向前伸直。
勾脚尖，收紧核心。
吸气准备，然后呼气，从髋部缓慢向前折叠。
双手伸向双脚，保持脊柱延展。
保持前屈姿势一个呼吸，然后缓慢回到直立位置。
重复完成目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-rear-flyes', '坐姿俯身后束飞鸟', 'seated bent-over rear delt fly', 'back', 'dumbbell', 1, 1, '每只手握一只哑铃，屈髋前倾直到躯干几乎与地面平行。
让哑铃垂在身前，肘部微屈。
双臂同时向两侧抬起，在顶端挤压肩胛骨。
在动作顶端停顿，然后缓慢将哑铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-machine-seated-row', '坐姿器械划船', 'machine seated row', 'back', 'machine', 1, 1, '坐在坐姿划船机上，双脚踩在踏板上，膝盖微屈。
以对握或正握握住把手，坐直身体。
将把手拉向躯干，肘部向后驱动，肩胛骨收紧。
在完全收缩位置停顿。
缓慢伸直双臂回到起始位置。
重复所需次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-chair-twist-upper-back', '坐姿椅上上背扭转', 'seated chair twist upper back', 'back', 'bodyweight', 1, 1, '坐在椅子上，背部挺直，双脚平放地面，双臂交叉于胸前。
保持髋部朝前不动，将上半身向一侧旋转。
保持旋转姿势片刻，感受上背部的拉伸。
回到中间位置，再向另一侧旋转。
继续交替进行至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-cable-row', '坐姿绳索划船机', 'seated cable row', 'back', 'cable', 1, 1, '坐在坐姿划船器上，双脚踩在踏板上，膝盖微屈。
握住V形把手或缆绳把手，坐直，脊柱中立。
将把手拉向下腹部，肘部向后驱动。
在完全收缩位置将肩胛骨挤压在一起。
缓慢伸直双臂回到起始位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-chest-supported-machine', '坐姿胸部支撑器械划船', 'seated chest supported machine', 'back', 'machine', 1, 1, '面向胸部支撑划船机坐下，将胸部紧贴靠垫。
双手以对握或正握握住把手。
肩胛骨后缩，肘部向后拉，将把手拉向身体。
在收缩顶点停顿，挤压背阔肌和菱形肌。
缓慢将把手放回起始位置，重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-spinal', '坐姿脊柱活动', 'seated spinal', 'back', 'bodyweight', 1, 1, '坐在地面上，双腿向前伸直。
双手放在身后地面上做轻微支撑。
坐直，通过头顶向上提拉来延展脊柱。
按目标时长保持直立姿势。
保持稳定呼吸，专注于维持脊柱长而中立。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-iron-cross-stretch', '坐姿铁十字拉伸', 'seated iron cross stretch', 'back', 'bodyweight', 1, 1, '坐在地面上，双腿向前伸直。
弯曲右膝，右脚跨过左腿，平放在左膝外侧的地面上。
左肘放在右膝外侧，轻轻施压使躯干向右旋转。
右臂向后伸展支撑，目光越过右肩。
保持拉伸20-30秒，然后缓慢放松，换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-iron-cross-stretch-version1', '坐姿铁十字拉伸式1', 'seated iron cross stretch version1', 'back', 'bodyweight', 1, 1, '坐在地面上，双腿向前伸直。
右脚踝交叉放在左大腿膝盖上方，右脚保持勾脚。
双手放在臀部两侧地面支撑，坐直。
躯干轻轻向弯曲的膝盖方向旋转，用手保持平衡。
保持20-30秒，感受下背部和髋部的旋转，然后换侧。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-kettlebell-pullover-to-glute-raise', '壶铃上拉接臀举', 'kettlebell pullover to glute raise', 'back', 'kettlebell', 1, 2, '仰卧，屈膝双脚踩地，双手持壶铃置于胸部上方。
以拉举动作将壶铃向头后方下放，感受背阔肌拉伸。
将壶铃回到胸部上方，同时将髋部抬离地面做臀桥。
将髋部放回地面，然后重复拉举动作。
持续至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-child-pose', '婴儿式', 'child pose', 'back', 'bodyweight', 1, 1, '跪在地上，大脚趾相触，膝盖与髋同宽。
坐回脚跟，然后躯干前屈，双臂向前伸直放在地面上。
额头轻触地面，肩膀向地面放松。
保持20-30秒，深呼吸，让背部拉长。
慢慢将双手收回，起身回到起始位置。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-child-pose-upper-back-slightly-bent-stretch', '婴儿式上背微屈拉伸', 'Child Pose Upper Back Slightly Bent Stretch', 'back', 'bodyweight', 1, 1, '跪在地上，坐向脚跟。
双臂向前伸，但肘部保持微屈，让上背部自然拱起。
胸部向地面下沉，感受上背部的拉伸。
保持20-30秒，同时深呼吸。
回到跪姿并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-child-pose-upper-back-straight-stretch', '婴儿式上背直伸拉伸', 'Child Pose Upper Back Straight Stretch', 'back', 'bodyweight', 1, 1, '跪在地板上，臀部坐向脚跟。
双臂充分向前伸展，肘部伸直，手掌平贴地面。
保持脊柱挺直，双臂向下按压地面，主动拉长背部。
保持20-30秒，平稳呼吸。
回到跪姿并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-child-s-pose', '婴儿式伸展', 'child''s pose', 'back', 'bodyweight', 1, 1, '跪在垫子上，双膝与髋同宽，脚趾并拢。
臀部坐向脚跟，躯干向前折叠伏在大腿上。
双臂沿垫子向前伸直，掌心向下。
让额头贴在垫子上，放松全身。
保持所需时间，深呼吸以释放背部和髋部的紧张。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-full-wheel-entry-wheel-prep-bridge', '完整轮式进入-轮式预备桥', 'full wheel entry - wheel prep bridge', 'back', 'bodyweight', 1, 3, '仰卧，双膝弯曲，双脚平放在靠近臀部的地面上。
双手放在耳朵两侧的地面上，手指朝向肩膀。
同时用手和脚发力，将臀部抬离地面，然后抬起躯干。
尽量伸展手臂和腿，将头顶抬离地面，打开胸腔。
保持目标时长，然后收下巴，有控制地缓慢回到地面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wide-grip-pull-up', '宽握引体向上', 'wide grip pull-up', 'back', 'bodyweight', 1, 3, '正握引体向上杆，握距宽于肩宽。
双臂完全伸展悬垂，收紧核心。
将肘部向下拉向髋部，带动身体向上。
继续上拉直到下巴超过横杆。
在顶端稍作停顿，挤压背阔肌。
缓慢下放回到完全悬垂位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lat-pull-down-wide-grip', '宽距高位下拉', 'lat pull down wide grip', 'back', 'cable', 1, 1, '坐在高位下拉器上，以宽于肩的正握握住横杆。
调整膝垫固定双腿，身体略微后仰。
肘部向下向后发力，将横杆拉向上胸。
在动作底部收紧背阔肌。
缓慢让横杆回到起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hyperextensions-back-extensions', '山羊挺身', 'hyperextensions (back extensions)', 'back', 'bodyweight', 1, 1, '俯卧于罗马椅，髋部置于垫子边缘，双脚固定。
双臂交叉于胸前或双手置于脑后。
以腰部为轴，控制身体缓慢下放。
收缩下背部和臀肌，将躯干抬起至身体呈一条直线。
在顶端稍作停顿，重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-back-extension-glute-focus', '山羊挺身（臀肌侧重）', 'back extension (glute focus)', 'back', 'machine', 1, 1, '在罗马椅/超伸展凳上就位，髋部位于垫子边缘，双脚固定。
双臂交叉于胸前或向前伸展。
上背部略微弓起，伸展髋部时专注于臀部发力。
上升至身体成一条直线或略高于平行位置。
缓慢降回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-rocker-with-open-legs', '开腿摇', 'rocker with open legs', 'back', 'bodyweight', 1, 2, '坐在垫子上，屈膝，双脚抬离地面。
抓住脚踝，将双腿伸直成V形，以坐骨保持平衡。
收紧核心，下背部略微拱起。
吸气向后摇，滚到上背部，同时保持V形。
呼气摇回平衡位置。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bow-pose-dhanurasana', '弓式', 'bow pose (dhanurasana)', 'back', 'bodyweight', 1, 2, '俯卧在垫子上，双腿伸直，双臂放在身体两侧。
屈膝，脚跟靠近臀部，向后伸手用双手抓住脚踝。
吸气，双脚压向双手，同时将胸部和大腿抬离垫子。
保持双膝与髋同宽，目视前方。
保持姿势20-30秒，深呼吸，然后呼气，轻轻回到垫子上。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-pull-up', '引体向上', 'pull up', 'back', 'bodyweight', 1, 2, '以略宽于肩的正握悬垂在引体向上杆上。
收紧核心，避免身体摆动。
通过将肘部向下向后驱动将身体向上拉，直到下巴超过杆。
在顶部停顿并挤压背阔肌。
缓慢下降到完全悬垂位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-assisted-pull-up', '引体向上（辅助）', 'assisted pull up', 'back', 'other', 1, 1, '在辅助引体向上机器上设置好目标配重，跪或站在平台上。
以略宽于肩的正握握住横杆。
收紧核心，将身体向上拉，直到下巴超过横杆。
在顶端短暂停顿，夹紧肩胛骨。
缓慢降回起始位置，手臂完全伸展。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-pull-apart-rear-delt-focus', '弹力带-俯身后束飞鸟', 'banded pull-apart (rear delt focus)', 'back', 'band', 1, 1, '双手在肩高握住阻力带，双臂向前伸展。
保持与肩同宽的握距，肘部微屈。
双手向身体两侧向外水平移动，将阻力带拉开。
在拉动末端重点收紧后三角肌和肩胛骨。
缓慢回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-w-raise', '弹力带W字上举', 'resistance band w-raise', 'back', 'band', 1, 1, '双脚与肩同宽站立，双手握住弹力带两端。
双臂在身前抬至肩高，肘部微屈。
将弹力带向两侧拉开并向后拉，屈肘使双臂形成W形。
动作末端夹紧肩胛骨。
缓慢回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-row', '弹力带划船', 'banded row', 'back', 'band', 1, 1, '将阻力带固定在胸部高度的固定点，双手各握住一端。
后退以让阻力带产生张力，双脚与肩同宽站立。
将阻力带拉向躯干，肘部向后拉，并将肩胛骨向内收紧。
在收缩峰值稍停，然后缓慢将双臂伸回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-band-row-to-triceps', '弹力带划船接臂屈伸', 'band row to triceps', 'back', 'band', 1, 1, '将阻力带固定在胸高处，面向固定点站立。
双手握住阻力带，后退一步制造张力。
以划船动作将阻力带拉向躯干，夹紧肩胛骨。
划船末端，双臂向后伸展做三头肌后踢动作。
有控制地返回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-curls-to-high-rows', '弹力带弯举接高位划船', 'banded curls to high rows', 'back', 'band', 1, 2, '将阻力带固定于低处，面向固定点站立，双手各握一端。
先做肱二头肌弯举，双手举向肩部。
在弯举顶端肘部向外展开，将阻力带向上拉向下巴做高位划船。
缓慢反向动作，经弯举路径还原至起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-pull-apart', '弹力带拉开', 'banded pull-apart', 'back', 'band', 1, 1, '双脚与肩同宽站立，双手在肩高握住阻力带，双臂向前伸展。
肘部保持微屈，双手向身体两侧向外移动，将阻力带拉开。
在完全拉开位置将肩胛骨向内收紧。
缓慢将双手回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-deadlift', '弹力带硬拉', 'resistance band deadlift', 'back', 'band', 1, 1, '双脚与髋同宽踩住弹力带中间。
双手在体侧握住弹力带，掌心相对，屈髋前倾。
整个动作中保持背部平直、胸部挺起。
脚跟发力，伸展髋部站直。
在顶部停顿，髋部完全伸展。
缓慢屈髋回到起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-lat-pulldown', '弹力带高位下拉', 'resistance band lat pulldown', 'back', 'band', 1, 1, '双脚与肩同宽直立。
双手握住弹力带，握距略宽于肩，双臂伸直举过头顶。
收紧核心，肘部向下向外发力将弹力带拉开。
将弹力带拉至颈后，直至到达上背部，同时挤压肩胛骨。
缓慢控制阻力，将双臂回到头顶起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-back-row', '弹力绳-俯身划船', 'banded back row', 'back', 'band', 1, 1, '将阻力带固定在胸部高度，或坐在地上将阻力带套在双脚上。
正握阻力带两端，双臂在身前完全伸直。
坐直或站直，身体略微前倾，脊柱保持中立。
肘部向后驱动，肩胛骨夹紧，将阻力带拉向躯干。
完全收缩时停顿，然后缓慢还原至起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-one-arm-row', '弹力绳-单手划船', 'banded one arm row', 'back', 'band', 1, 1, '将阻力带一端固定在低处，侧身站在固定点旁并面向固定点。
一只手握住阻力带另一端，手臂朝固定点方向伸展。
收紧核心，背部保持平直，髋部略微铰链前倾。
通过将肘部向后拉，把阻力带拉向髋部，在顶部收紧背阔肌。
缓慢回到起始位置，按目标次数重复后换手臂。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-seated-row', '弹力绳-坐姿划船', 'banded seated row', 'back', 'band', 1, 1, '坐在地面上，双腿伸直，将阻力带绕过双脚。
双手握住阻力带，手臂伸直，背部挺直。
肘部向后拉，将阻力带拉向下腹部。
在收缩位置夹紧肩胛骨。
缓慢伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-banded-lat-pulldown', '弹力绳-高位下拉', 'banded lat pulldown', 'back', 'band', 1, 1, '将阻力带固定在上方固定点，在固定点下方跪姿或坐姿。
双手握住阻力带，握距略宽于肩。
双臂向上伸展，通过将肘部拉向髋部，把阻力带下拉至胸前。
在动作底部收紧背阔肌。
缓慢让双臂回到上方伸展位置，并按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-arm-stretching-hug-yourself', '抱臂拉伸', 'Arm Stretching Hug Yourself', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，双臂自然垂于身体两侧。
双臂在胸前交叉，每只手环抱对侧肩膀，如同拥抱自己。
轻轻将肩膀向前拉，保持拉伸20-30秒。
放松，按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wide-grip-seated-cable-row', '拉杆坐姿划船(宽握)', 'wide grip seated cable row', 'back', 'cable', 1, 2, '将直杆连接到低位滑轮，坐在踏板上，膝盖微屈。
正握直杆，握距宽于肩宽。
坐直，将杆拉向下胸部，肘部向外展开。
在收缩位置将肩胛骨挤压在一起。
缓慢伸直手臂回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-corpse-pose-shavasana', '摊尸式', 'corpse pose (shavasana)', 'back', 'bodyweight', 1, 1, '仰卧平躺，双腿伸展并略微分开。
双臂放在身体两侧，掌心向上，略微离开身体。
闭上眼睛，让双脚自然向外倒。
放松所有肌肉用力，自然呼吸，让全身放松。
保持此姿势5-10分钟，然后缓慢加深呼吸，轻轻转向一侧后再坐起。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-modified-superman-hold-legs-grounded', '改良超人式保持（腿贴地）', 'modified superman hold (legs grounded)', 'back', 'bodyweight', 1, 1, '俯卧于地面，双腿伸直，双臂向前伸展过头。
保持双腿平贴地面，专注于仅将胸部和手臂抬离地面。
抬起时收紧臀肌并激活下背部肌肉。
在抬起位置保持目标时长。
缓慢将胸部和手臂降回地面，重复动作。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-good-morning', '早安', 'good morning', 'back', 'barbell', 1, 2, '双脚与肩同宽站立，将杠铃置于上背部。
保持背部平直并收紧核心。
膝盖微屈，髋部铰链前倾，躯干下降至接近与地面平行。
在底部停顿，感受腘绳肌拉伸。
髋部前推回到直立起始姿势。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-rocking-pilate', '普拉提摇', 'rocking pilate', 'back', 'bodyweight', 1, 3, '俯卧在垫子上，屈膝，双脚向臀肌方向抬起。
向后伸手，用双手抓住脚踝。
收紧核心，同时将胸部和大腿抬离垫子。
以受控的弧线向前摇到胸部，再向后摇到大腿。
按所需次数继续前后摇动。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-conventional-deadlift', '杠铃传统硬拉', 'barbell conventional deadlift', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，杠铃位于脚中部上方。
以髋部铰链前倾，用正握或正反握在双腿外侧握住杠铃。
收紧核心，保持背部平直，通过蹬地发力提起杠铃。
杠铃贴近身体，同时伸展髋部和膝盖。
在顶部完全站直，髋部充分伸展、肩部后收，然后将杠铃控制下放回地面。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-bent-over-row', '杠铃俯身提拉', 'barbell bent over row', 'back', 'barbell', 1, 2, '双脚与肩同宽站立，以略宽于肩的正手握距握住杠铃。
屈髋向前俯身约45度，保持背部平直。
让杠铃自然下垂、手臂伸直，然后将其拉向下胸部。
在动作顶端夹紧肩胛骨。
缓慢将杠铃放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-row', '杠铃划船', 'barbell row', 'back', 'barbell', 1, 2, '双脚与肩同宽站立，正握杠铃，握距略宽于肩。
以髋部为轴俯身，直至躯干大致与地面平行，保持背部平直。
将杠铃拉向下胸部，肘部向后发力，肩胛骨收紧。
在顶部稍作停顿，然后缓慢将杠铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-landmine-stiff-stance-deadlift', '杠铃地雷管直腿硬拉', 'landmine stiff stance deadlift', 'back', 'barbell', 1, 2, '将杠铃固定在地雷管套中，背对固定点站立，双脚与髋同宽。
双手在身后或体侧握住杠铃末端。
屈髋并略微屈膝，将杠铃向地面下放。
整个动作过程中保持背部平直、核心收紧。
脚跟发力回到站立，在顶部收紧臀肌。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-good-morning-barbell', '杠铃早安式', 'good morning barbell', 'back', 'barbell', 1, 2, '将杠铃置于上斜方肌处如做背蹲，双脚与肩同宽站立。
膝盖微屈，髋部铰链前倾，髋部后推，躯干下降。
继续下降至躯干约与地面平行，或感到腘绳肌强烈拉伸。
在底部停顿，然后髋部前推回到直立起始姿势。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-good-morning-to-behind-neck-shoulder-press', '杠铃早安式接颈后推举', 'barbell good morning to behind neck shoulder press', 'back', 'barbell', 1, 3, '将杠铃置于上背部，双脚与肩同宽站立。
屈髋前倾，膝盖微屈，将躯干向地面下放。
保持背部平直，下放至腘绳肌有拉伸感。
回到直立位置，然后将杠铃从颈后推过头顶。
将杠铃放回上背部，重复该序列。
按目标次数持续进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-deadlift-barbell', '杠铃硬拉', 'deadlift barbell', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，杠铃置于脚中部上方。
屈髋屈膝，双手在腿外侧握杠。
深吸气，收紧核心，挺胸保持背部平直。
脚跟发力提起杠铃，同时伸展髋部和膝盖。
顶部站直，然后屈髋屈膝，控制杠铃放回地面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-deadlift-to-curl', '杠铃硬拉接弯举', 'barbell deadlift to curl', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，杠铃置于身前地面。
屈髋俯身，反握杠铃，保持背部平直。
脚跟发力站直，完成硬拉。
在硬拉顶端，屈肘将杠铃弯举至胸前。
有控制地将杠铃下放，回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-deadlift-to-press', '杠铃硬拉接推举', 'barbell deadlift to press', 'back', 'barbell', 1, 3, '双脚与髋同宽站立，杠铃置于身前地面。
屈髋俯身，正握杠铃，保持背部平直。
脚跟发力站直，完成硬拉。
在顶端耸肩将杠铃上提，过渡为过顶推举，将杠铃推过头顶。
有控制地将杠铃放回肩部，再放回地面。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-shrug', '杠铃耸肩', 'barbell shrug', 'back', 'barbell', 1, 1, '直立站立，双脚与肩同宽，正握杠铃置于大腿前方。
双臂自然下垂，保持背部挺直、胸部上提。
以耸肩动作将双肩尽可能向耳朵方向抬高。
在顶部短暂停顿并收紧斜方肌。
缓慢将双肩放回起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-tabletop-start-thoracic-bridge', '桌面起始-胸椎桥', 'tabletop start - thoracic bridge', 'back', 'bodyweight', 1, 1, '坐在地面上，屈膝，双脚平放，双手放在身后，手指朝向身体。
通过双手和双脚发力，抬起臀部，直到身体形成与地面平行的桌面姿势。
收紧臀肌，头部微微后仰，胸部向上打开。
保持桌面姿势2-3秒，然后慢慢将臀部放回地面。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-meadows-row', '梅多斯划船', 'meadows row', 'back', 'barbell', 1, 2, '将杠铃固定在杠铃地雷架或房间角落。
侧身站在杠铃旁，单手正握杠铃末端。
髋部铰链前倾至约45度，膝盖微屈。
将杠铃末端向上拉向髋部，肘部向后驱动。
在顶部停顿，收紧背阔肌和上背部。
缓慢将杠铃放回起始位置，重复后换边。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chair-back-hand-raise-up-stretch', '椅子背后抬手拉伸', 'chair back hand raise up stretch', 'back', 'bodyweight', 1, 1, '坐在椅子上，保持上身直立，双脚平放地面。
双臂伸直举过头顶，向天花板方向延伸。
向上伸展时拉长脊柱，让身体两侧和背部得到轻柔拉伸。
保持姿势20–30秒。
放下双臂，按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chair-back-stretch-hand-behind-back', '椅子背后拉伸-手在背后', 'chair back stretch - hand behind back', 'back', 'bodyweight', 1, 1, '坐在椅子上，保持上身直立，双手放到背后并十指交叉。
轻轻将肩膀向后拉，并将肩胛骨向内挤压。
抬起胸部并保持姿势20–30秒。
松开双手，放松后重复。
按所需次数进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chair-back-overhead-stretch', '椅子背后过顶拉伸', 'chair back overhead stretch', 'back', 'bodyweight', 1, 1, '坐在椅子上，保持上身挺直，双脚平放地面。
双手十指交叉并举过头顶，掌心向上。
轻轻向一侧倾斜，以拉伸背部和身体侧面的侧向拉伸。
保持20–30秒，然后回到中间并向相反一侧倾斜。
每侧按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bodyweight-half-standing-row-with-towel', '毛巾半站姿划船', 'Bodyweight Half Standing Row With Towel', 'back', 'bodyweight', 1, 1, '双手握住绕在牢固柱子或门把手上的毛巾两端。
身体后倾约45度，双臂伸直，双脚靠近固定点。
屈肘向后拉，将胸部拉向固定点。
在顶端夹紧肩胛骨。
缓慢伸直双臂回到起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-swim-dive', '游泳式俯冲', 'swim dive', 'back', 'bodyweight', 1, 2, '俯卧，双臂过头伸直，双腿伸直。
收紧核心，将手臂、胸部和双腿抬离垫面。
同时将双臂向两侧并向后扫向髋部，如跳水动作。
双臂回到过头位置并重复。
全程保持视线向下，颈部中立。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-swimming-pilate', '游泳式普拉提', 'swimming pilate', 'back', 'bodyweight', 1, 2, '俯卧在垫上，双臂过头伸直，双腿伸直。
收紧核心，将手臂、胸部和双腿略微抬离垫面。
交替将右臂和左腿抬得更高，同时降低对侧肢体。
持续做上下打水的游泳动作，吸气5拍，呼气5拍。
全程保持视线向下以维持颈部中立。
按目标呼吸循环次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-pendlay-row', '潘德雷划船', 'pendlay row', 'back', 'barbell', 1, 2, '站在杠铃上方，双脚与肩同宽，屈髋前倾至躯干与地面平行。
以正握、与肩同宽的握距握住杠铃，双臂完全伸直。
从完全静止开始，爆发性地将杠铃拉向下胸部。
每次重复之间将杠铃完全放回地面。
重新调整姿势，再次上拉。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-inverted-row', '澳式引体', 'inverted row', 'back', 'bodyweight', 1, 1, '将杠铃或吊环设置在腰部高度，仰卧在其下方。
以正握、与肩同宽的握距握住杠铃，双臂完全伸展悬垂。
保持身体从头到脚跟呈一条直线。
通过向后收肘将胸部拉向杠铃。
在顶部停顿，夹紧肩胛骨。
缓慢下降回到起始位置并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cow-pose-bitilasana', '牛式', 'cow pose (bitilasana)', 'back', 'bodyweight', 1, 1, '从四点跪姿开始，手腕位于肩下，膝盖位于髋下。
深吸气，腹部向垫面下沉，让脊柱拱起。
胸口和尾骨向天花板抬起，打开身体前侧。
肩膀放松，远离耳朵。
短暂保持，然后呼气过渡到猫式，按5-10个呼吸循环重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cow-pose-stretch', '牛式拉伸', 'cow pose stretch', 'back', 'bodyweight', 1, 1, '从四点跪姿开始，手腕正对肩下，膝盖位于髋下。
吸气，缓慢让腹部向地面下沉，抬头并向上抬尾骨。
保持拱起姿势2-3秒，感受胸部和下背部拉伸。
呼气，将脊柱回到中立位。
按目标次数重复，并配合呼吸完成动作。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plough-pose-halasana', '犁式', 'plough pose (halasana)', 'back', 'bodyweight', 1, 2, '仰卧平躺，双臂放在身体两侧，手掌压地。
收紧核心，将臀部抬离地面，双腿举过头顶。
双腿伸直，脚趾向头后方的地面下放。
在背后垫子上十指交叉以增加支撑。
保持姿势20-30秒，然后脊柱逐节缓慢卷回垫上。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-sphinx-pose-bhujangasana', '狮身人面式', 'sphinx pose (bhujangasana)', 'back', 'bodyweight', 1, 1, '面朝下趴在垫子上，双腿伸直，脚背压向地面。
前臂平放于垫上，肘部位于肩膀正下方。
吸气，前臂轻压垫子，将胸部和上腹部抬离地面。
保持骨盆和下腹部贴于垫上，目视前方。
保持30-60秒，深呼吸，然后将胸部放回垫上。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-gorilla-row', '猩猩划船', 'gorilla row', 'back', 'dumbbell', 1, 2, '将两只哑铃放在地面，髋部铰链前倾，保持背部平直握住两只哑铃。
将右侧哑铃向髋部方向拉起，左侧哑铃作为支撑。
放下右侧哑铃，立即将左侧哑铃向上拉起。
以有节奏的方式持续交替划船。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-upper-back', '猫式上背', 'cat pose upper back', 'back', 'bodyweight', 1, 1, '四肢着地，双手位于肩膀下方，膝盖位于髋部下方。
呼气，将中背部向上推，重点在胸椎区域拱起。
头部垂于双臂之间，保持3-5秒。
缓慢回到平背位置。
按目标次数重复，每次专注于上背部。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-upper-back-1', '猫式上背1', 'cat pose upper back 1', 'back', 'bodyweight', 1, 1, '以四肢着地，呈中立桌面姿势开始。
缓慢将上背部向天花板方向拱起，同时保持下背部相对不动。
将肩胛骨向两侧展开，以最大化上背部拉伸。
保持姿势5秒，平稳呼吸。
回到中立位，按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-upper-back-advanced', '猫式上背进阶', 'cat pose upper back advanced', 'back', 'bodyweight', 1, 3, '以四肢着地，呈桌面姿势开始。
在上背部拱起进入猫式的同时，深度收下巴并将肚脐向内收。
保持顶峰收缩5-8秒，主动用手掌推离地面。
缓慢回到中立位，然后立即流畅进入深度塌腰的牛式。
在猫式与牛式之间交替，按所需次数重复，每轮保持猫式更久。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-stretch', '猫式伸展', 'cat pose stretch', 'back', 'bodyweight', 1, 1, '四肢着地，双手位于肩膀正下方，膝盖位于髋部正下方。
呼气，脊柱向上拱向天花板，下巴收向胸口。
保持拱起姿势2-3秒，感受上背部的拉伸。
缓慢回到脊柱中立位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-to-forward-fold', '猫式到前屈', 'cat pose to forward fold', 'back', 'bodyweight', 1, 1, '四肢着地呈桌面姿势。
脊柱向上拱起进入猫式，收紧下巴和尾骨。
从猫式将髋部向后推向脚跟，进入婴儿式或前屈姿势。
保持前屈20-30秒，感受背部和髋部的拉伸。
回到四肢着地，按目标次数重复转换。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-stretching', '猫式拉伸', 'cat pose stretching', 'back', 'bodyweight', 1, 1, '四肢着地，手腕位于肩膀正下方，膝盖位于髋部正下方。
吸气准备，然后呼气，脊柱向上拱向天花板，下巴收向胸口，尾骨内收。
保持拱起姿势2-3秒，感受背部的拉伸。
缓慢将脊柱回到中立位置。
配合呼吸按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-stretch-version-1', '猫式拉伸版本1', 'cat pose stretch version 1', 'back', 'bodyweight', 1, 1, '四肢着地呈桌面姿势，脊柱保持中立。
呼气，缓慢向上拱起背部，头部和尾骨向地面下沉。
保持拉伸3-5秒，专注于胸椎区域。
吸气，回到中立起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-pose-version-1', '猫式版本1', 'cat pose version 1', 'back', 'bodyweight', 1, 1, '以四肢着地开始，脊柱中立，双手位于肩下。
缓慢呼气，同时从颈部到尾骨拱起整个脊柱。
将腹部向内收，同时骨盆内卷。
保持完整脊柱屈曲3-5秒。
吸气并缓慢回到中立位后重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-cow-stretch', '猫牛式拉伸', 'cat-cow stretch', 'back', 'bodyweight', 1, 1, '四肢着地，双手位于肩膀正下方，膝盖位于髋部正下方。
吸气，腹部向垫面下沉，抬头并将尾骨抬向天花板（牛式）。
呼气，脊柱向天花板拱起，下巴收向胸口，骨盆内收（猫式）。
配合呼吸在猫式和牛式之间流畅交替。
按目标呼吸循环次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cat-cow-back-stretch', '猫牛式背部拉伸', 'cat cow back stretch', 'back', 'bodyweight', 1, 1, '四肢着地，手腕位于肩膀正下方，膝盖位于髋部正下方。
吸气，腹部向地面下沉，同时抬起胸部和尾骨向上（牛式）。
呼气，背部向天花板拱起，收紧下巴和尾骨（猫式）。
以缓慢可控的节奏在猫式和牛式之间交替。
按目标次数或时长重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-deadlift-sumo-barbell', '相扑杠铃硬拉', 'deadlift sumo barbell', 'back', 'barbell', 1, 2, '双脚宽于肩站立，脚尖外展，杠铃置于脚中部上方。
双手在腿内侧握杠，采用正握或正反握。
收紧核心，挺胸，膝盖向外推与脚尖方向一致。
脚跟发力提杠，髋部和膝盖同步伸展。
顶部完全站直，然后控制杠铃放回地面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-barbell-deadlift', '硬拉', 'barbell deadlift', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，杠铃位于双脚中部上方。
以髋部铰链前倾并屈膝，用正握或正反握在双腿外侧握住杠铃。
收紧核心，保持胸部挺起，确保背部平直后再开始提起。
通过脚跟发力，同时伸展髋部和膝盖提起杠铃。
在顶部完全站直，然后以髋部铰链控制下放杠铃回地面。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-prayer-forward-fold', '祈祷前屈', 'Prayer Forward Fold', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双手在胸前合十呈祈祷姿势。
以髋部为轴前屈，保持背部平直，将躯干向地面下放。
双臂可向前伸展或放在身前以加深拉伸。
保持20-30秒，深呼吸。
缓慢起身回到站立，按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-negative-pull-up', '离心引体向上', 'negative pull up', 'back', 'bodyweight', 1, 2, '使用箱子或跳跃到达引体向上的顶部位置，下巴高于横杆，手臂弯曲。
以正手握距、与肩同宽握住横杆。
缓慢将身体下放至起始悬垂位置，下降过程用3-5秒。
在整个下降过程中保持背阔肌和手臂的张力，尽可能抵抗重力。
完全伸展后，跳起或踩回顶部，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-close-grip-lat-pull-down', '窄距下拉', 'close grip lat pull down', 'back', 'cable', 1, 1, '将窄握或对握把手安装在高位下拉器的高滑轮上。
坐下并将大腿固定在垫子下方，用对握握住把手。
将把手拉向上胸部，肘部向下向后发力。
在动作底部收紧背阔肌。
缓慢将把手回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-y-t-w-stretch-series', '站姿Y-T-W拉伸系列', 'Standing Y-T-W Stretch Series', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，髋部微微前屈。
双臂举过头顶呈Y形，向上向内挤压肩胛骨。
将双臂向两侧展开至肩高呈T形，挤压中背部。
弯曲肘部向后拉成W形，将肩胛骨向中间收拢。
在每个姿势之间缓慢流动20-30秒，保持呼吸受控。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-bow-and-arrow', '站姿拉弓', 'Standing Bow and Arrow', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，双臂前平举至肩高。
弯曲一侧手肘向后拉，如拉弓弦，同时躯干向该侧旋转。
稍作停顿，感受胸部、肩部和背部的拉伸。
回到起始位置，换另一侧重复。
继续交替进行至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-cat-cow-spine-wave', '站姿猫牛式（脊柱波浪）', 'Standing Cat–Cow (Spine Wave)', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双手放在大腿上。
吸气，弓背挺胸，尾骨上翘进入牛式。
呼气，拱起脊柱，收下巴和骨盆进入猫式。
在两个位置之间继续流畅转换。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-cat-cow-spine-wave-1', '站姿猫牛式（脊柱波浪）1', 'Standing Cat–Cow (Spine Wave) 1', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双臂向上伸直。
从顶部开始脊柱波浪运动，先弓上背，再弓中背，再弓下背。
继续向下传递波浪运动，然后反向向上回传。
保持动作流畅并与呼吸协调。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-cable-row', '站姿绳索划船', 'standing cable row', 'back', 'cable', 1, 2, '将把手连接至约腰高的绳索滑轮，面向器械站立。
单手或双手握住把手，后退一小步制造张力。
直立站立，核心收紧，髋部微微铰链。
肘部向后驱动，肩胛骨收紧，将把手拉向躯干。
缓慢回到起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-rib-intercostal-stretch', '站姿肋间拉伸', 'Standing Rib Intercostal Stretch', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，将一侧手臂举过头顶。
将躯干向对侧倾斜，从举起的手到髋部形成长弧线。
保持侧向拉伸20-30秒，感受肋骨和背阔肌的拉伸。
回到直立位置并换另一侧。
按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-scapular-w-stretch', '站姿肩胛W拉伸', 'Standing Scapular W Stretch', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，将手臂抬至肩高。
弯曲肘部形成W形，前臂朝上。
将肩胛骨夹紧并保持2-3秒。
放松并回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-shoulder-blade-clock', '站姿肩胛骨时钟', 'Standing Shoulder Blade Clock', 'back', 'bodyweight', 1, 1, '站直，双脚与髋同宽，双臂自然垂于体侧。
缓慢地让肩胛骨完成完整的圆周运动，先向上耸肩。
继续顺时针将肩胛骨向后、向下、再向前滚动。
完成目标圈数后反方向进行。
保持颈部放松，全程平稳呼吸。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-back-extension-stretch', '站姿背部伸展拉伸', 'Standing Back Extension Stretch', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双手放在下背部，手指朝下。
轻轻将髋部向前推并向后仰，伸展脊柱。
保持姿势2-3秒，感受下背部拉伸。
回到直立位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-back-hug-yourself-stretch-upper-back', '站姿背部抱肩拉伸(上背)', 'Standing Back "Hug Yourself" Stretch (Upper Back)', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立。
双臂交叉抱于胸前，每只手抱住对侧肩膀。
轻轻将肩膀向前拉，上背部拱起。
保持拉伸20-30秒，深呼吸。
放松并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-back-stretch-interlaced-fingers-behind-ba', '站姿背部拉伸(背后交叉手指)', 'Standing Back Stretch(Interlaced Fingers Behind Ba', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，双手在背后十指交叉。
伸直手臂，将指关节向下压。
同时挺胸并将肩膀向后拉，感受背阔肌和胸部拉伸。
保持20-30秒。
放松并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-standing-back-fly-stretch', '站姿背部飞鸟拉伸', 'Standing Back Fly Stretch', 'back', 'bodyweight', 1, 1, '双脚与肩同宽站立，髋部略微前倾。
双臂在胸前高度向前伸直，掌心相对。
以飞鸟动作将双臂向后向外展开，夹紧肩胛骨。
控制动作回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-pull', '绳索拉', 'cable pull', 'back', 'cable', 1, 1, '将把手连接到绳索器械，并将滑轮调到所需高度。
握住把手，双脚与肩同宽站立，膝盖微屈。
通过向后向下带动肘部，将把手拉向躯干。
在完全收缩位置稍作停顿，收紧背部肌肉。
控制伸展，缓慢回到起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-straight-arm-pulldown', '绳索直臂下压', 'cable straight arm pulldown', 'back', 'cable', 1, 2, '将直杆连接到绳索器械的高滑轮。
面向器械站立，以正握握住直杆，手臂向上伸展。
保持手臂伸直，以宽幅弧线将直杆向下拉向大腿。
在动作底部稍作停顿，收紧背阔肌。
缓慢将直杆放回头顶起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-kneeling-row-meadow-alternate', '绳索跪姿划船（梅多交替）', 'cable kneeling row (meadow alternate)', 'back', 'cable', 1, 2, '将单手把手连接到低位滑轮，单膝跪地面向器械。
用与支撑膝相对的手握住把手，手臂完全伸直。
收紧核心，保持躯干直立并略微前倾。
肘部向后拉，将把手拉向髋部，收紧背阔肌。
在完全收缩处停顿，然后缓慢回到起始位置。
完成目标次数后换边。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-face-pull-up', '绳索面拉上拉', 'cable face pull up', 'back', 'cable', 1, 1, '将绳索滑轮调至胸部上方高度，并连接绳索把手。
双手握住绳索，后退以在绳索中产生张力。
将绳索拉向面部，分开双手，将双肘向后向外驱动。
当双手位于耳旁且双肘与肩同线时停顿。
缓慢将双臂伸回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-yates-row', '耶茨划船', 'yates row', 'back', 'barbell', 1, 2, '双脚与髋同宽站立，以略宽于肩的反握握住杠铃。
髋部前倾至约70度的较直立角度，比标准俯身划船更直立。
将杠铃拉向下腹部，肘部向后驱动。
在收缩位置停顿，收紧背阔肌。
缓慢将杠铃放回起始位置。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-interlaced-fingers-behind-back-bent-forward-stretch', '背后交叉手指前屈拉伸', 'Interlaced Fingers Behind Back Bent Forward Stretch', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双手在背后十指交叉。
伸直手臂，轻轻将其拉离背部。
以髋部为轴前屈，降低躯干，让交握的双手向上抬起过头。
保持20–30秒，感受胸部、肩部和背部的拉伸。
缓慢回到站立姿势并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-back-stretch', '背部拉伸', 'Back Stretch', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双臂前伸至肩高。
上背部拱起，双臂轻轻前推，让肩胛骨分开。
保持拉伸20-30秒，感受上背部张力。
放松，恢复直立站姿。
按需重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-t-spine-rotation', '胸椎旋转', 't-spine rotation', 'back', 'bodyweight', 1, 1, '从四点跪姿开始，双手位于肩下，膝盖位于髋下。
将一只手放在头后，肘部朝外。
旋转上身，将肘部尽量朝天花板打开至舒适范围。
在末端稍作停顿，然后回到起始位置。
按目标次数重复，然后换边。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-chest-extension', '胸部伸展', 'chest extension', 'back', 'bodyweight', 1, 1, '俯卧在垫子上，双臂伸直放在身体两侧，掌心朝上。
收紧核心，夹紧臀部。
将胸部和上半身抬离垫子至舒适高度，保持颈部中立。
在动作顶端稍作停留。
慢慢将胸部放回垫子。
按所需次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bodyweight-roman-deadlift', '自重罗马尼亚硬拉', 'Bodyweight Roman Deadlift', 'back', 'bodyweight', 1, 1, '双脚与髋同宽站立，双臂自然垂于体侧。
以髋为轴，臀部后推，保持背部平直、膝盖微屈。
躯干下降至感到腘绳肌拉伸。
脚跟发力，夹紧臀肌回到站立。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-dance-pose-natarajasana', '舞王式', 'dance pose (natarajasana)', 'back', 'bodyweight', 1, 3, '以山式站直，重心均匀分布在双脚上。
重心移到左脚，屈右膝，将右脚向后抬起。
右手抓住右脚踝或右脚，开始将躯干向前倾。
左臂向前伸直，右脚压向手掌以将腿抬得更高。
保持平衡20-30秒，然后松开并换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-scorpion-pose-vrschikasana', '蝎子式（Vrschikasana）', 'scorpion pose (vrschikasana)', 'back', 'bodyweight', 1, 3, '从海豚式开始，前臂平放垫上，臀部抬高。
双脚向手走近，直到臀部叠于肩上方，进入前臂头倒立。
平衡后，缓慢屈双膝，将双脚向脑后下放。
下背拱起，胸腔上提，双脚下降时形成深度脊柱弯曲。
保持10-20秒，然后小心将双脚放回垫上，在婴儿式中休息。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-locust-pose-salabhasana', '蝗虫式', 'locust pose (salabhasana)', 'back', 'bodyweight', 1, 1, '俯卧在垫子上，双腿伸直，双臂放在身体两侧，掌心朝上。
额头轻轻放在垫子上。
吸气，同时将头、胸、手臂和双腿抬离地面。
目光向前下方看，肩胛骨向内收拢，收紧臀部。
保持20-30秒，然后呼气，慢慢将身体放回垫子上。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-superman-hold', '超人式保持', 'superman hold', 'back', 'bodyweight', 1, 1, '俯卧在垫子上，双臂向前伸直过头，双腿伸直。
同时将双臂、胸部和双腿抬离地面。
在动作顶端收紧臀部和下背部。
保持该姿势2至3秒。
缓慢回到起始位置。
重复至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-upper-body-bent-back-stretch', '靠墙上半身前屈后伸拉伸', 'wall upper body bent back stretch', 'back', 'bodyweight', 1, 1, '背靠墙站立，双脚距墙约一英尺。
上身前屈，缓慢离开墙面，下背部轻贴墙。
双臂向下伸向地面，感受上下背部拉伸。
保持拉伸姿势20-30秒。
回到直立贴墙姿势。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-upper-back-and-hips-stretch', '靠墙上背与髋部拉伸', 'wall upper back and hips stretch', 'back', 'bodyweight', 1, 1, '面向墙壁站立，双手放在与肩同高的墙面上，双臂伸展。
双脚向后走，直到躯干前倾弯曲，双臂完全伸展。
同时将髋部向后推，胸部向地面压，拉伸上背部和髋部。
保持姿势20-30秒。
双脚向前走，恢复站立。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-upper-back-reverse-bent-squat', '靠墙上背反屈深蹲', 'wall upper back reverse bent squat', 'back', 'bodyweight', 1, 2, '背靠墙站立，双脚与肩同宽。
背部沿墙下滑至蹲姿，直到大腿与地面平行。
上背部微微贴墙拱起，双臂向前伸展。
保持姿势，收紧上背部和核心。
沿墙滑回站立，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-support-squat-hand-raise', '靠墙支撑深蹲抬手', 'wall support squat hand raise', 'back', 'bodyweight', 1, 2, '背靠墙壁站立，沿墙下滑进入深蹲，直到大腿与地面平行。
进入深蹲姿势后，双臂向前伸直抬至与肩同高。
保持深蹲和双臂抬起姿势目标时长。
放下双臂，沿墙滑回站起。
按目标组数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-slide-pilate', '靠墙普拉提滑臂', 'wall slide pilate', 'back', 'bodyweight', 1, 1, '背贴墙站立，双脚与髋同宽，距墙几英寸。
下背、上背和头部压墙。
双臂抬至球门柱姿势，手背和前臂压墙。
双臂沿墙缓慢向上滑过头顶，全程保持接触。
双臂滑回球门柱姿势。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-standing-upper-body-bent-stretch', '靠墙站姿上半身前屈拉伸', 'wall standing upper body bent stretch', 'back', 'bodyweight', 1, 1, '面向墙壁站立，双脚与髋同宽，双手平放在与腰同高的墙面上。
双脚向后走，直到躯干弯曲至与地面平行，双臂完全伸展。
双手推墙，将髋部拉离墙壁以拉长脊柱。
保持拉长姿势20-30秒，深呼吸。
双脚走回，恢复站立。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-standing-upper-back-stretch-version-1', '靠墙站姿上背拉伸式一', 'wall standing upper back stretch version 1', 'back', 'bodyweight', 1, 1, '面向墙壁站立，双手平放在与肩同高的墙面上。
双脚向后走，直到双臂完全伸展，躯干弯曲约45度。
双手推墙，让胸部向地面下沉，上背部拱起。
保持拉伸姿势20-30秒。
双脚向墙走回，恢复站立。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-standing-cat-pose-stretch', '靠墙站姿猫式拉伸', 'wall standing cat pose stretch', 'back', 'bodyweight', 1, 1, '面向墙壁站立，双手平放于墙面与肩同高处。
双脚向后走，直到手臂完全伸直、躯干与地面呈45度角。
收紧核心，像猫式一样将上背部向上拱起，下巴收向胸口。
保持拱起姿势片刻，然后轻轻向反方向弓背。
交替重复拱背和弓背动作至目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-arms-standing-feet-touch', '靠墙站立手臂触足', 'wall arms standing feet touch', 'back', 'bodyweight', 1, 1, '面向墙壁站立，双脚并拢，脚尖距墙根数英寸。
双臂向上伸展，双手尽可能高地放在墙上。
从髋部缓慢前屈，双手沿墙向下移动，降低躯干。
继续直到胸部朝向地面，双臂沿墙伸展。
保持拉伸姿势20-30秒，感受背阔肌和腘绳肌的牵拉感。
双手沿墙缓慢向上移回站立姿势并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-hinge-stretcher', '靠墙髋铰链拉伸', 'wall hinge stretcher', 'back', 'bodyweight', 1, 1, '面向墙站立，双脚与髋同宽，距离约一臂长。
双手放在墙上与肩同高。
屈髋将臀部后推，下压躯干直到背部平直并与地面平行。
保持屈髋拉伸20-30秒，感受下背和腘绳肌的拉伸。
回到站立并重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-hinge-stretcher-1', '靠墙髋铰链拉伸一', 'wall hinge stretcher 1', 'back', 'bodyweight', 1, 1, '侧对墙站立，一只手放在墙上支撑。
保持背部平直屈髋，将躯干向前伸展。
另一只手放在下背以监测脊柱对齐。
保持屈髋姿势20-30秒，专注下背的拉伸。
回到直立，换另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cable-face-pull', '面拉', 'cable face pull', 'back', 'cable', 1, 1, '将绳索把手连接到绳索器械，滑轮调至约面部高度，面向器械站立。
以正手握法双手握住绳索，后退直至双臂伸直。
通过将双肘向外向后驱动，将绳索拉向面部。
在面部高度分开绳索两端，使双手位于头部两侧。
缓慢回到起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-airplane-pose-dekasana', '飞机式', 'airplane pose (dekasana)', 'back', 'bodyweight', 1, 2, '双脚并拢站直，双臂向两侧伸展至肩高。
将重心移至右脚，以髋部为轴前倾，同时将左腿向后方笔直抬起。
继续前倾躯干直至身体形成与地面平行的直线。
保持双臂大幅伸展，视线略微向前以帮助平衡。
保持该姿势20-30秒，然后缓慢回到站立并在另一侧重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-fish-pose-matsyasana', '鱼式（Matsyasana）', 'fish pose (matsyasana)', 'back', 'bodyweight', 1, 1, '仰卧平躺，双腿伸直，双臂放于身体两侧。
双手滑入臀部下方，掌心朝下。
前臂和肘部压向垫面，将胸部抬向天花板，上背部拱起。
轻轻后仰头部，将头顶轻放于地面。
保持20-30秒，然后抬起头，松开双手，将背部放回垫面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bird-dog', '鸟狗式', 'bird dog', 'back', 'bodyweight', 1, 1, '四点跪姿开始，双手位于肩部正下方，膝盖位于髋部正下方。
收紧核心，整个动作过程中保持背部平直。
同时向前伸展右臂、向后伸展左腿，两者均与地面平行。
保持2-3秒，然后回到起始位置。
换对侧重复，伸展左臂和右腿，按目标次数交替进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bird-dog-leg-lift', '鸟狗式抬腿', 'bird dog leg lift', 'back', 'bodyweight', 1, 1, '四点跪姿开始，双手位于肩部正下方，膝盖位于髋部正下方。
收紧核心，向前伸直一侧手臂，同时向后伸直对侧腿。
短暂保持姿势，髋部保持水平，脊柱保持中立。
回到起始位置，换对侧手臂和腿重复。
按目标次数交替进行。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-bird-dog-advanced-both-hands-raise', '鸟狗式进阶（双手抬起）', 'bird dog advanced (both hands raise)', 'back', 'bodyweight', 1, 3, '四点跪姿开始，双手位于肩部正下方，膝盖位于髋部正下方。
收紧核心稳定脊柱，保持背部平直。
同时向前伸直双臂、向后伸展双腿，以躯干保持平衡。
保持姿势2-3秒，维持脊柱中立，避免旋转。
回到起始位置，按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-crane-pose-bakasana', '鹤式', 'crane pose (bakasana)', 'back', 'bodyweight', 1, 3, '从低蹲开始，双脚靠近，双手平放在身前地面。
肘部微屈，将膝盖放在上臂后侧。
重心向前倾到双手上，先抬起一只脚，再抬起另一只脚离地。
收紧核心并略微拱背，保持团身姿势。
保持10-20秒，然后缓慢将双脚放回地面。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-vipr-lateral-shuffle', 'VIPR侧向滑步', 'vipr lateral shuffle', 'cardio', 'other', 1, 2, '将ViPR管垂直或水平握于胸前。
保持ViPR位置，开始向一侧横向滑步。
数步后向相反方向滑步。
全程保持低位运动站姿和核心收紧。
持续至目标时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-zig-zag-walk', '之字形走', 'zig zag walk', 'cardio', 'bodyweight', 1, 1, '在地面上标出之字形路线，或想象一系列锥桶。
以之字形快步行走，每次变向时左右跨步。
保持步伐可控，核心收紧。
随着协调性提高，加快到快走或轻慢跑。
按目标趟数继续之字形路线。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-crossover-high-knee-cardio', '交叉高抬腿有氧', 'crossover high knee cardio', 'cardio', 'bodyweight', 1, 1, '双脚与肩同宽站立，双臂向两侧伸展。
同时将右膝向上并横过身体朝左肘方向驱动。
回到起始位置，随即左膝朝右肘方向驱动。
以轻快、有节奏的动作继续交替两侧。
全程保持身体直立并收紧核心。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-on-floor-marching', '仰卧原地踏步', 'lying on floor marching', 'cardio', 'bodyweight', 1, 1, '仰卧平躺，双臂放在身体两侧。
开始以行军模式交替将膝盖抬向胸部。
手臂摆动与对侧腿部动作协调配合。
保持稳定、受控的节奏。
持续目标时间。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-senior-friendly-burpee-low-impact-joint-safe', '低冲击波比跳', 'senior-friendly burpee (low-impact, joint-safe)', 'cardio', 'bodyweight', 1, 1, '双脚与肩同宽站立，双臂垂于体侧。
缓慢屈髋屈膝，双手放在身前地面上。
一次一只脚向后迈入平板支撑位置，避免跳跃。
短暂保持平板支撑，然后一次一只脚迈回双手附近。
双手放在膝盖上，缓慢推起回到站立位置。
以可控节奏重复目标次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lateral-sprint-shuffles', '侧向冲刺滑步', 'lateral sprint shuffles', 'cardio', 'bodyweight', 1, 2, '以低重心运动姿势站立，膝盖微屈，重心放在前脚掌。
蹬内侧脚向一侧滑步，反复迈步并拢双脚。
全程保持髋部低位、胸部抬起。
达到目标距离后，外侧脚蹬地，向反方向滑回。
继续来回滑步，持续目标时间。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lateral-shuffle', '侧向滑步', 'lateral shuffle', 'cardio', 'bodyweight', 1, 1, '从低重心运动姿势开始，屈膝，双脚与肩同宽。
蹬内侧脚，向一侧横向滑步。
轻柔落地并立即向另一方向蹬回。
全程保持快速、连续的滑步节奏。
持续目标时间。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-sprint-interval-fast-running', '冲刺间歇跑', 'sprint interval fast running', 'cardio', 'bodyweight', 1, 2, '从站立或慢跑热身开始，然后过渡到全速冲刺。
向前驱动膝盖并有力摆臂，以最大化跑速。
在规定的冲刺时长内保持最大努力，通常为10-30秒。
减速为慢跑或步行，进行规定的恢复期。
重复冲刺和恢复间歇至目标轮数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-sprint-intervals-fast-running', '冲刺间歇跑', 'sprint intervals fast running', 'cardio', 'bodyweight', 1, 3, '以轻度慢跑开始热身肌肉。
加速至最大冲刺，专注于有力摆臂和高抬膝。
在规定的间歇时长内保持冲刺，通常为15-30秒。
通过步行或慢跑进行规定的休息恢复。
重复至目标间歇次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-boating', '划船式', 'boating', 'cardio', 'bodyweight', 1, 1, '坐在较高的箱子或台阶上，身体稍向后倾，双脚离地，以臀部保持平衡。
双手斜握一个负重圆柱物体（如木棍或晃管），横跨身体。
收紧核心，躯干向一侧扭转，将圆柱一端向下压，如同划皮艇。
平稳地将躯干转向另一侧，将圆柱另一端向下压。
保持双脚抬起，维持流畅连续的划桨动作。
持续左右交替至目标时长或次数。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-rowing-machine', '划船机', 'rowing machine', 'cardio', 'machine', 1, 1, '坐在划船机上，双脚固定在绑带中，双手握住把手。
起始时屈膝、身体略前倾、双臂伸直。
蹬腿伸膝，同时身体略微后仰。
双腿完全伸展时，屈肘将把手拉向下胸部。
反向还原至起始姿势，按目标时长重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-jump-for-beginners', '初学者跳跃', 'jump for beginners', 'cardio', 'bodyweight', 1, 1, '双脚与髋同宽站立，双臂自然垂于体侧。
微屈膝，双臂向后摆动。
双脚发力跳起数英寸离地。
前脚掌轻柔落地，膝盖微屈缓冲冲击。
以舒适节奏按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lateral-shuffle-1', '前后交替滑步', 'forward-back shuffle', 'cardio', 'bodyweight', 1, 1, '以运动姿势站立，膝盖微屈，双脚与肩同宽。
向一侧快速做两到三步滑步，保持低重心。
外侧脚蹬地，立即向反方向滑同样步数。
全程保持髋部低位，重心放在前脚掌。
继续左右滑步，持续目标时间。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hand-raise-front-jumping-jack', '前平举开合跳', 'hand raise front jumping jack', 'cardio', 'bodyweight', 1, 1, '直立站立，双脚并拢，双臂垂于体侧。
双脚跳开至与肩同宽，同时将双臂向体前伸直举至肩高。
双脚跳回并拢，双臂放下回到起始位置。
以较快节奏连续重复该动作。
持续目标次数或时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-cycling', '动感单车（有氧）', 'cycling', 'cardio', 'machine', 1, 1, '坐上固定自行车，调整座椅高度，使踏板完全伸展时腿部略微弯曲。
双脚放入踏板束带中，握住车把。
以舒适的踏频开始骑行，保持直立或前倾姿势。
根据需要调整阻力，达到目标强度。
持续目标时长，然后逐渐减速进入放松节奏。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-place-jog', '原地慢跑', 'place jog', 'cardio', 'bodyweight', 1, 1, '双脚与髋同宽站立。
开始原地慢跑，交替将每只脚抬离地面。
以前脚掌保持轻盈有弹性的节奏。
自然摆臂，与腿部动作配合。
持续目标时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-place-jog-cardio', '原地慢跑有氧', 'place jog cardio', 'cardio', 'bodyweight', 1, 1, '双脚与髋同宽站立，双臂自然垂于体侧。
以舒适的速度开始原地慢跑，每一步将脚抬离地面几英寸。
自然摆臂，与腿部协调配合。
保持上身直立，核心轻微收紧，目视前方。
持续目标时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-run-in-place', '原地跑-Tabata', 'run in place', 'cardio', 'bodyweight', 1, 1, '直立站立，双脚与髋同宽。
开始原地跑，双脚交替抬离地面。
双臂屈肘90度，与双腿自然反向摆动。
逐渐加快至舒适的跑步速度。
保持稳定动作至目标时长。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hand-behind-interlock-high-knee-cardio', '双手背后交叉高抬腿有氧', 'hand behind interlock high knee cardio', 'cardio', 'bodyweight', 1, 2, '直立站立，双手在头后交叉扣紧，肘部向外打开。
