INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-chair-march', '坐姿椅上踏步', 'seated chair march', 'cardio', 'bodyweight', 1, 1, '端坐椅上，双脚平放地面，双手放在大腿上。
