INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-reverse-bike', '仰卧反向单车', 'lying reverse bike', 'core', 'bodyweight', 1, 2, '仰卧，双腿抬至90度桌面位置。
