INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-vertical-crunches-legs-straight-up', '仰卧垂直卷腹（双腿伸直向上）', 'lying vertical crunches (legs straight up)', 'core', 'bodyweight', 0, 2, '仰卧，双腿伸直向上抬起，垂直于地面。
