INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-vertical-crunches-legs-straight-up-advance', '仰卧垂直卷腹（双腿伸直向上）进阶', 'lying vertical crunches (legs straight up) advance', 'core', 'bodyweight', 0, 3, '仰卧，双腿伸直向上抬起。
