INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-vertical-flutter-kicks-lying', '仰卧垂直打腿', 'vertical flutter kicks (lying)', 'core', 'bodyweight', 1, 2, '仰卧平躺，双手放在臀部下方支撑。
