INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-bent-leg-scissor', '仰卧屈腿剪刀', 'lying bent leg scissor', 'core', 'bodyweight', 1, 1, '仰卧，双臂放在身体两侧。
