INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-leg-raise-bent-knees', '仰卧屈膝举腿', 'lying leg raise (bent knees)', 'core', 'bodyweight', 1, 1, '仰卧平躺，双腿伸直，双手放在下背部下方或平放于身体两侧。
