INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-bike-bent-knee', '仰卧屈膝单车', 'lying bike bent knee', 'core', 'bodyweight', 1, 1, '仰卧，双手轻放在头后。
