INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-supine-recovery-breathing', '仰卧恢复呼吸', 'supine recovery breathing', 'core', 'bodyweight', 0, 1, '仰卧平躺，双膝弯曲，双脚平放地面，或将双腿抬高放在平面上。
