INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-in-and-outs-hold', '坐姿收放腿保持', 'seated in-and-outs hold', 'core', 'bodyweight', 1, 2, '坐在地面上，双手放在臀部两侧支撑。
