INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-hold-with-one-hand-and-leg-lift', '平板支撑单手单腿抬起', 'Plank Hold With One Hand and Leg Lift', 'core', 'bodyweight', 1, 2, '从完整平板支撑开始，手臂伸直。
同时抬起一只手臂和对侧腿，两者均伸直。
短暂保持伸展姿势，同时保持臀部水平。
