INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-with-one-hand-lift', '平板支撑单手抬起', 'plank with one hand lift', 'core', 'bodyweight', 1, 2, '从高平板支撑开始，双手位于肩膀正下方。
