INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-jack', '平板支撑开合跳', 'plank jack', 'core', 'bodyweight', 1, 1, '从前臂或高位平板支撑开始，身体从头到脚跟保持一条直线。
