INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-knee-to-chest', '平板支撑提膝至胸', 'Plank Knee To Chest', 'core', 'bodyweight', 1, 1, '从完整平板支撑开始，手臂伸直，双手与肩同宽。
