INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-push-up-elbow', '平板支撑撑起至肘撑', 'Plank Push Up Elbow', 'core', 'bodyweight', 1, 2, '从前臂平板姿势开始，肘部位于肩膀正下方。
先撑起一只手，再撑起另一只手，过渡到完整俯卧撑平板。
