INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-medicine-plank-to-toe-tap', '平板支撑触脚尖', 'medicine plank to toe tap', 'core', 'other', 1, 2, '从平板支撑开始，双手放在药球上。
