INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-twist', '平板支撑转体', 'plank twist', 'core', 'bodyweight', 1, 2, '从前臂平板支撑开始，肘部位于肩膀正下方，身体保持一条直线。
收紧核心，将髋部向一侧旋转，向地面下压。
在触地前停顿，然后向另一侧旋转。
以受控、有节奏的动作继续左右交替。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-hold-with-hips-twist', '平板支撑转髋', 'plank hold with hips twist', 'core', 'bodyweight', 1, 2, '从前臂平板支撑开始，肘部位于肩膀正下方。
保持肩膀方正，旋转臀部并向一侧下沉至地面方向。
在臀部触地前停住，然后旋转到另一侧。
以可控且有节奏的方式继续交替扭转。
按目标次数重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-plank-hip-dip', '平板支撑髋部下压', 'plank hip dip', 'core', 'bodyweight', 1, 1, '从前臂平板支撑开始，肘部位于肩膀正下方，身体成一条直线。
