INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-control-balance', '平衡控制', 'control balance', 'core', 'bodyweight', 1, 3, '仰卧平躺，双腿向上翻越头部，直到脚趾触及头后方的垫子。
用双手支撑下背部，或将双臂压向垫子。
一条腿垂直向上抬向天花板，另一条腿保持伸展在头后方。
稍作停留，然后以受控的剪刀式动作交换双腿。
继续交替至目标次数，然后缓慢滚回垫子上。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-resistance-band-kneeling-crunch', '弹力带-跪姿卷腹', 'resistance band kneeling crunch', 'core', 'band', 1, 1, '将弹力带固定在上方，面向固定点跪在垫子上。
