INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hanging-leg-raises', '悬垂举腿', 'hanging leg raises', 'core', 'bodyweight', 1, 2, '正握单杠悬垂，握距与肩同宽，双臂完全伸直。
收紧核心，保持双腿伸直，在身前向上抬起。
