INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hanging-leg-raise', '悬垂直腿上举', 'hanging leg raise', 'core', 'bodyweight', 1, 2, '正握单杠悬垂，双臂完全伸直，双脚离地。
