INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-decline-elbow-plank-hold', '靠墙下斜肘撑平板支撑', 'wall decline elbow plank hold', 'core', 'bodyweight', 1, 2, '前臂撑地，双脚抬高抵在墙上。
肘部对准肩部正下方，从头到脚跟保持一条直线。
收紧核心、臀部和肩部，维持下斜平板姿势。
