INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-lying-leg-and-hips-lift-up', '靠墙仰卧腿臀上抬', 'wall lying leg and hips lift up', 'core', 'bodyweight', 1, 2, '仰卧，双臂平放地面体侧，双腿沿墙向上伸展。
