INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-plank-hold', '靠墙平板支撑', 'wall plank hold', 'core', 'bodyweight', 1, 2, '双手平放地面，双脚沿墙上行，直到身体与地面平行。
