INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-plank-one-leg-up-down', '靠墙平板支撑单腿抬起', 'wall plank one leg up down', 'core', 'bodyweight', 1, 2, '面向墙站立，双手与肩同高平贴墙面。
