INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-marching-hand-on-wall', '靠墙扶墙踏步', 'wall marching hand on wall', 'core', 'bodyweight', 1, 1, '面向墙壁站立，双手与肩同高平贴墙面。
