INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-legs-up-the-wall-viparita-karani', '靠墙抬腿', 'legs up the wall (viparita karani)', 'core', 'bodyweight', 1, 1, '侧身坐在墙边，双腿上摆的同时将背部放低到地面。
