INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-wall-support-plank-leg-on-wall', '靠墙支撑平板撑腿搭墙', 'wall support plank leg on wall', 'core', 'bodyweight', 1, 2, '在墙边就位，双手撑地呈标准平板支撑姿势。
