INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-adductor-stretch-feet-elevated', '仰卧内收肌拉伸-脚抬高', 'lying adductor stretch – feet elevated', 'legs', 'bodyweight', 1, 1, '仰卧在墙边，双脚搭在墙上，膝盖微屈。
