INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-adductor-stretch-feet-elevated-version-1', '仰卧内收肌拉伸-脚抬高变式1', 'lying adductor stretch – feet elevated version 1', 'legs', 'bodyweight', 1, 1, '仰卧，臀部靠近墙壁，双脚搭在墙上。
