INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-wide-leg-stretch', '仰卧宽距腿拉伸', 'lying wide leg stretch', 'legs', 'bodyweight', 1, 2, '仰卧平躺，双腿向上抬起朝向天花板。
