并拢双腿后重复。', '[]', 1, 'vital_animations', 'Vital Animations EULA 2026.1', NOW()) ON DUPLICATE KEY UPDATE name_zh=VALUES(name_zh), name_en=VALUES(name_en), muscle_group=VALUES(muscle_group), equipment=VALUES(equipment), is_compound=VALUES(is_compound), difficulty=VALUES(difficulty), instructions=VALUES(instructions), source=VALUES(source), license=VALUES(license);
