INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-quads-stretch-ii', '仰卧股四头肌拉伸II', 'lying quads stretch ii', 'legs', 'bodyweight', 0, 1, '俯卧地面，双腿伸直。
