INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-lying-leg-cycle', '仰卧蹬腿画圈', 'lying leg cycle', 'legs', 'bodyweight', 1, 1, '仰卧平躺，双手放在臀部下方支撑。
