INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-side-lying-leg-raise', '侧卧抬腿', 'side lying leg raise', 'legs', 'bodyweight', 1, 1, '侧卧，双腿叠放，身体呈一条直线。
