INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-seated-on-knee-high-dive-advanced', '跪姿俯冲进阶', 'seated on knee high dive advanced', 'legs', 'bodyweight', 1, 3, '双膝跪立，核心收紧，躯干挺直。
