INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-kneeling-quad-extension', '跪姿腿屈伸', 'kneeling quad extension', 'legs', 'bodyweight', 1, 3, '双膝跪在垫子上，身体保持直立。
