INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-hip-flexor-stretch-kneeling', '跪姿髋屈肌拉伸', 'hip flexor stretch (kneeling)', 'legs', 'bodyweight', 1, 1, '单膝跪地，另一脚平放在身前地面，双膝均约呈90度。
