INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-sit-on-knee-hip-rotate', '跪膝髋部旋转', 'sit on knee hip rotate', 'legs', 'bodyweight', 1, 1, '跪于地面，坐在脚跟上。
