INSERT INTO exercises (slug, name_zh, name_en, muscle_group, equipment, is_compound, difficulty, instructions, contraindications, is_active, source, license, created_at) VALUES ('vital-jump-box-beginners', '跳箱初学者', 'jump box beginners', 'legs', 'bodyweight', 1, 1, '站在低跳箱或台阶前。
